import { ChangeDetectionStrategy, ChangeDetectorRef, Component, EventEmitter, Input, OnInit, Output } from '@angular/core';
import { CommonModule } from '@angular/common';
import { DocInfo, globAnnot, myTeamUsers, temporaryAnnots, toolEvents } from '../../../interfaces/pdf.interface';
import { IconComponent } from '../../../../shared/components/icon/icon.component';
import { FormsModule } from '@angular/forms';
import { SourceCardComponent } from '../../../../shared/components/source-card/source-card.component';
import { SharedViewComponent } from '../../../../shared/components/shared-view/shared-view.component';
import { CommonService } from '../../../../shared/services/common/common.service';
import { ButtonComponent } from '../../../../shared/components/button/button.component';
import { WebService } from '../../../../shared/services/webs/web.service';
import { TostbarService } from '../../../../core/services/tost/tostbar.service';
import { CommonfunctionService } from '../../../../core/utility/commonfunction.service';
import { environment } from '../../../../../environments/environment';
import { linkType } from '../../../../shared/interfaces/common.interface';

import { TranslateService, TranslateModule } from '@ngx-translate/core';

@Component({
  selector: 'webform',
  standalone: true,
  imports: [CommonModule, IconComponent, ButtonComponent, FormsModule, SourceCardComponent, SharedViewComponent, TranslateModule],
  changeDetection: ChangeDetectionStrategy.OnPush,
  templateUrl: './webform.component.html',
  styleUrl: './webform.component.scss'
})
export class WebformComponent implements OnInit {
  @Input() docInfo: DocInfo = {} as DocInfo;
  @Input() tempAnnots: temporaryAnnots[] = [];
  @Input() nCaseid: string;
  @Output() OnEvent = new EventEmitter<toolEvents>();
  @Input() selectedlinktype: linkType = {} as linkType;
  @Input() annotGlobMode: globAnnot;
  userList: myTeamUsers[] = [];

  cUrl: string = '';
  isUrlverified: boolean = false;
  isValidurl: boolean = false;
  isSubmitted: boolean = false;
  cTitle: string = '';
  cNote: string = '';
  viewTitlebox: boolean = false;
  cIco: string = '';
  cImg: string = '';
  isLoading: boolean = false;
  imagepath: any = `${environment.cloudUrl}${environment.downloadpath}`
  constructor(private web: WebService, private common: CommonService, private cdr: ChangeDetectorRef, private tost: TostbarService, private cf: CommonfunctionService, private translate: TranslateService) { }

  async ngOnInit() {

    try {
      if (this.annotGlobMode == 'S') {
        const pages = this.tempAnnots.map(a => a.annots?.page);
        this.selectedlinktype = { type: 'H', start: this.selectedlinktype.start || 0, end: this.selectedlinktype.end || 0, pages: [...new Set(pages)] };
      } else {
        this.selectedlinktype = { type: this.selectedlinktype["mode"], start: this.selectedlinktype.start, end: this.selectedlinktype.end };
      }
    } catch (error) {

    }

    this.userList = await this.common.getMyTeamUsers(this.nCaseid);
    this.cdr.detectChanges();
  }

  back() {
    this.OnEvent.emit({ event: 'CLOSE', data: {} });
  }

  async getWebData() {

    this.isUrlverified = false;
    this.cdr.detectChanges();
    if (!this.cUrl)
      return
    if (!this.cUrl.includes('http'))
      this.cUrl = 'https://' + this.cUrl;
    if (!this.OnValidateUrl()) {
      this.tost.error(this.translate.instant('PDF.WEBFORM.INVALID_URL'));
      return;
    }
    if (this.isLoading) return;
    this.isLoading = true;
    const res = await this.web.getUrlData(this.cUrl, this.nCaseid);
    this.isLoading = false;

    if (res) {

      try {
        if (res.matadata) {
          this.cTitle = res.matadata.title;
          this.cNote = res.matadata.description;
        }
      } catch (error) {

      }

      try {
        if (res.favicon) {
          this.cIco = res.favicon;
        }
        if (res.screenshot) {
          this.cImg = res.screenshot;
        }
      } catch (error) {

      }

      this.viewTitlebox = true;
      this.isUrlverified = true;
    }
    this.cdr.detectChanges();

  }

  OnValidateUrl() {
    this.isUrlverified = false;
    if (this.cf.validateUrl(this.cUrl)) {
      // this.isValidurl = true;
      return true;
      // this.getWebData();
    } else {
      return false;
      // this.isValidurl = false;
    }
  }

  async submit() {

    if (!this.isUrlverified) return;

    if (this.isSubmitted) {
      return;
    }
    this.isSubmitted = true;

    const mdl = {
      nBDid: this.docInfo.nBundledetailid,
      cUrl: this.cUrl,
      jAn: this.convToStr(this.tempAnnots.map(a => a.annots)),
      jOT: this.convToStr(this.tempAnnots.map(a => a.text).filter(a => a)),
      cTitle: this.cTitle || '',
      cNote: this.cNote || '',
      cFavicon: this.cIco,
      cImg: this.cImg,
      jUsers: this.convToStr(this.userList.filter(a => a.isSelected).map(a => a.nUserid)),
      cType: this.annotGlobMode,
      jLinktype: this.convToStr(this.selectedlinktype)
    };
    let res = await this.web.saveWeb(mdl);

    this.isSubmitted = false;
    this.cdr.detectChanges();
    if (res["msg"] == 1) {
      this.tost.openSnackBar(res["value"]);
      this.OnEvent.emit({ event: 'WEB-ADDED', data: { nWebid: res["nWebid"] } });
    } else {
      this.tost.error(this.translate.instant('PDF.WEBFORM.CREATION_FAILED'));
    }

  }

  convToStr(val: any) {
    return JSON.stringify(val);
  }


}
