import { ChangeDetectorRef, Component, EventEmitter, Input, Output } from '@angular/core';
import { ButtonComponent } from '../../../../shared/components/button/button.component';
import { IconComponent } from '../../../../shared/components/icon/icon.component';
import { NavigateService } from '../../../services/navigate/navigate.service';
import { SharedViewComponent } from '../../../../shared/components/shared-view/shared-view.component';
import { environment } from '../../../../../environments/environment';
import { DatePipe } from '@angular/common';

@Component({
  selector: 'webcard',
  standalone: true,
  imports: [ButtonComponent,IconComponent,SharedViewComponent,DatePipe],
  templateUrl: './webcard.component.html',
  styleUrl: './webcard.component.scss'
})
export class WebcardComponent {
  @Input() viewmode: string;
  @Input() x: any = {};
  @Input() userList: any = [];
  imagepath: any = `${environment.cloudUrl}${environment.downloadpath}`
  @Input() nCaseid: string;
  @Output() OnView: EventEmitter<any> = new EventEmitter();
  constructor(private navigateService: NavigateService, private cdr: ChangeDetectorRef) { }

  async showShared(x) {
    const users = await this.navigateService.getSharedUsers(x.nWebid, 'W');
    this.userList.map(f => f.isSelected = (users.findIndex(m => m.nUserid == f.nUserid) > -1))
    this.x.forEach(y => {
      if (y.nWebid != x.nWebid) {
        y['showShared'] = false
      }
    })
    x['showShared'] = !x['showShared']
    this.cdr.detectChanges();
  }

  OnViewEvent(x) {
    this.OnView.emit(x);
  }

}
