import { ChangeDetectionStrategy, ChangeDetectorRef, Component, EventEmitter, Input, Output, SimpleChange, ViewChild } from '@angular/core';
import { CommonModule } from '@angular/common';
import { DocInfo, FACTFROM, globAnnot, ModelType, myTeamUsers, PDFAnnotation, temporaryAnnots, toolEvents } from '../../interfaces/pdf.interface';
import { FactformComponent } from '../facts/factform/factform.component';
import { DocformComponent } from '../doc/docform/docform.component';
import { WebformComponent } from '../webs/webform/webform.component';
import { QuickfactComponent } from '../facts/quickfact/quickfact.component';
import { FactdataComponent } from '../linkviews/facts/factdata/factdata.component';
import { WebdataComponent } from '../linkviews/webdata/webdata.component';
import { linkType } from '../../../shared/interfaces/common.interface';
import { DocdataComponent } from '../linkviews/docdata/docdata.component';
import { QuickfactdataComponent } from '../linkviews/facts/quickfactdata/quickfactdata.component';
import { factdata } from '../../../shared/interfaces/fact.interface';
import { NavigateComponent } from '../../../userpanel/components/navigate/navigate.component';
import { LocationShareComponent } from '../../../userpanel/components/location-share/location-share.component';
import { CommonService } from '../../../shared/services/common/common.service';
import { IssuedialogComponent } from "../../../shared/components/issues/issuedialog/issuedialog.component";
import { PropertiesComponent } from '../../../shared/components/properties/properties/properties.component';
import { usersRes } from '../../../adminpanel/interfaces/permission.interface';
import { SecureStorageService } from '../../../core/services/storage/secure-storage.service';
import { IssueFormComponent } from '../../../shared/components/issues/issue-form/issue-form.component';
import { selectedContactList, selectedIssues } from '../../../shared/interfaces/issue.interface';
import { RolepermitService } from '../../../core/services/permission/rolepermit.service';
import { FactCreationComponent } from '../../../marking/components/fact/fact-creation/fact-creation.component';
import { TostbarService } from '../../../core/services/tost/tostbar.service';

@Component({
  selector: 'right-panel',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [FactformComponent, DocformComponent, WebformComponent, QuickfactComponent, FactdataComponent, WebdataComponent, DocdataComponent, QuickfactdataComponent, CommonModule,
    NavigateComponent, LocationShareComponent, IssuedialogComponent, IssuedialogComponent, PropertiesComponent, IssueFormComponent,
    FactCreationComponent],
  templateUrl: './right-panel.component.html',
  styleUrl: './right-panel.component.scss'
})
export class RightPanelComponent {
  @Input() cFFrom: FACTFROM = 'I';
  @Input() modeltype: ModelType;
  @Input() docInfo: DocInfo = {} as DocInfo;
  @Input() tempAnnots: temporaryAnnots[] = [];
  @Input() selectedIssues: any = [];
  @Input() nCaseid: string;
  @Input() nBundledetailid: string;
  @Output() OnEvent = new EventEmitter<toolEvents>();
  @Input() fullMode: boolean = false;
  @Input() linkIds: string[] = [];
  @Input() selectedlinktype: linkType = {} as linkType;
  @Input() annotGlobMode: globAnnot;
  @Input() globannots: PDFAnnotation[] = [];
  quickFactDetail: factdata | null = null
  @Input() userList: myTeamUsers[] = [];
  @Input() MselectedTab: any = 'A';
  @Input() factMode: any = null;
  @Input() jFiles: DocInfo[] = [];



  // @ViewChild(QuickfactComponent) quickFact!: QuickfactComponent;

  propertyview: boolean = false;
  nUserid: string;
  nViewissueid: number = 0;

  @Input() selectedContacts: selectedContactList[] = [];

  isContactPermission: boolean = false;
  isTaskPermission: boolean = true;

  constructor(private common: CommonService, private scureStorage: SecureStorageService, public cdr: ChangeDetectorRef,
    private rolepermit: RolepermitService,
    private tost: TostbarService
  ) { }

  OnLinkEvent(e: any) {
    this.quickFactDetail = null;
    if (e.event == 'CONVERT-TO-FACT') {
      // A Full Fact must commit to a real issue. "Unassigned" is the QFact's
      // implicit placeholder for "captured but not yet categorised" — converting
      // a QFact whose only issue is Unassigned would produce a Fact that's
      // structurally identical to the QFact and adds no value. Block the
      // conversion here so the user goes back and assigns a real issue first.
      const issues: any[] = e.data?.issueList || [];
      const hasRealIssue = issues.some(i => i?.cIName !== 'Unassigned');
      if (!hasRealIssue) {
        this.tost.error('Please assign at least one issue (other than Unassigned) before converting to a Full Fact.');
        return;
      }

      // this.tempAnnots.push(...annot)
      // this.OnEvent.emit({ event: 'CLEAR-TEMP-ANNOT', data: {} });
      this.tempAnnots.splice(0, this.tempAnnots.length);
      this.quickFactDetail = e.data;
      this.selectedIssues = [];
      const annot = this.globannots.filter(a => a.id == e.data.nFSid && a.linktype == 'QF');
      const jOText = e.data.jTexts || [];
      annot.forEach((a, index) => {
        a.linktype = 'F';
        this.tempAnnots.push({ annots: a, text: jOText[index] || '' });
      });
      this.modeltype = 'F';
      this.cdr.detectChanges()
      return;
    }
    if (e.event == 'EDIT-Q-FACT') {
      this.quickFactDetail = e.data;
      const annot = this.globannots.filter(a => a.id == e.data.nFSid && a.linktype == 'QF');
      const jOText = e.data.jTexts || [];
      annot.forEach((a, index) => {
        a.linktype = a.linktype || 'F';
        this.tempAnnots.push({ annots: a, text: jOText[index] || '' });
      });
      this.modeltype = 'QF';
      this.cdr.detectChanges()
      return;
    }
    if (e.event == 'FILTER-ISSUE-DETAIL') {
      this.nViewissueid = e.data.nIid;
    }
    this.cdr.detectChanges()
    this.OnEvent.emit(e);
    this.cdr.detectChanges();
  }


  async ngOnInit() {
    this.nUserid = await this.scureStorage.getUserId();
    this.verifyPermission();
    this.cdr.detectChanges()
    //Called after the constructor, initializing input properties, and the first call to ngOnChanges.
    //Add 'implements OnInit' to the class.
    // this.userList = await this.common.getMyTeamUsers(this.nCaseid);
  }
  ngAfterViewInit() {
    this.cdr.detectChanges()
  }

  ngOnChanges(changes: SimpleChange) {
    if (changes['modeltype'] && changes['modeltype'].currentValue != changes['modeltype'].previousValue) {
      this.OnEvent.emit({ event: 'COMPONENT-LOADED', data: {} });
    }
    this.cdr.detectChanges()
  }

  close() {
    this.OnEvent.emit({ event: 'CLOSE', data: {} });
    this.cdr.detectChanges();
  }


  onIssueselect(ev) {
    console.log('on issue selecet', ev);
    this.OnEvent.emit(ev);
    this.cdr.detectChanges();
  }

  submit() {
    // this.quickFact.submit();
  }


  async verifyPermission() {
    this.isContactPermission = this.rolepermit.verifyPermission('CT');
    this.isTaskPermission = this.rolepermit.verifyPermission('TS');
  }


}
