import { Component, EventEmitter, Input, Output } from '@angular/core';
import { ChooseIssueComponent } from '../choose-issue/choose-issue.component';
import { selectedIssues } from '../../../interfaces/issue.interface';
import { IconComponent } from '../../icon/icon.component';
import { ButtonComponent } from '../../button/button.component';

@Component({
  selector: 'app-issue-form',
  standalone: true,
  imports: [ChooseIssueComponent, IconComponent, ButtonComponent

  ],
  templateUrl: './issue-form.component.html',
  styleUrl: './issue-form.component.scss'
})

export class IssueFormComponent {
  @Input() nCaseid: string;
  @Input() selectedIssues: selectedIssues[] = [];
  showalert: boolean = false;
  @Output() onIssueselect = new EventEmitter<any>();


  submit() {
    this.onIssueselect.emit({ event: 'ISSUE_SUBMIT', data: this.selectedIssues })
  }
  close() {
    this.onIssueselect.emit({ event: 'CLOSE', data: {} })
  }

  issueevent(ev) {
    if (ev.event == 'ISSUE_CHNAGE') {
      this.selectedIssues = ev.data;
    }
  }



}
