import { ChangeDetectionStrategy, ChangeDetectorRef, Component, EventEmitter, Input, OnInit, Output } from '@angular/core';
import { DocInfo, globAnnot, myTeamUsers, temporaryAnnots, toolEvents } from '../../../interfaces/pdf.interface';
import { IconComponent } from '../../../../shared/components/icon/icon.component';
import { SourceCardComponent } from '../../../../shared/components/source-card/source-card.component';
import { SharedViewComponent } from '../../../../shared/components/shared-view/shared-view.component';
import { CommonService } from '../../../../shared/services/common/common.service';
import { ButtonComponent } from '../../../../shared/components/button/button.component';
import { MatDialog, MatDialogRef } from '@angular/material/dialog';
import { FileexplorerComponent } from '../../../../shared/components/myfiles/fileexplorer/fileexplorer.component';
import { CommonModule } from '@angular/common';
import { TranslateModule } from '@ngx-translate/core';
import { DocService } from '../../../../shared/services/docs/doc.service';
import { TostbarService } from '../../../../core/services/tost/tostbar.service';
import { linkType } from '../../../../shared/interfaces/common.interface';
import { DOCFORM_STATIC } from '../../../interfaces/docform.interface';
import { ErrorHandlerUtil } from '../../../../userpanel/utility/error-handler.util';

@Component({
  selector: 'docform',
  standalone: true,
  imports: [IconComponent, SourceCardComponent, SharedViewComponent, ButtonComponent, CommonModule, TranslateModule],
  changeDetection: ChangeDetectionStrategy.OnPush,
  templateUrl: './docform.component.html',
  styleUrl: './docform.component.scss'
})
export class DocformComponent implements OnInit {

  @Input() docInfo: DocInfo = {} as DocInfo;
  @Input() tempAnnots: temporaryAnnots[] = [];
  @Input() nCaseid: string;
  @Output() OnEvent = new EventEmitter<toolEvents>();
  @Input() selectedlinktype: linkType = {} as linkType;
  userList: myTeamUsers[] = [];
  dialogRef: MatDialogRef<FileexplorerComponent> | null = null;
  jFiles: DocInfo[] = [];
  isSubmitted: boolean = false;
  @Input() annotGlobMode: globAnnot;

  constructor(private readonly doc: DocService, private readonly common: CommonService, private readonly cdr: ChangeDetectorRef, private readonly dialog: MatDialog, private readonly tost: TostbarService) { }

  ngOnInit(): void {
    void this.initialize();
  }

  private async initialize(): Promise<void> {
    try {
          if (this.annotGlobMode === DOCFORM_STATIC.annotGlobModeS) {
            const pages = this.tempAnnots.map(a => a.annots?.page);
            this.selectedlinktype = { type: DOCFORM_STATIC.selectedLinkTypeH, start: this.selectedlinktype?.start ?? 0, end: this.selectedlinktype?.end ?? 0, pages: [...new Set(pages)] };
      } else {
        this.selectedlinktype = { type: this.selectedlinktype?.type, start: this.selectedlinktype?.start, end: this.selectedlinktype?.end };
      }
    } catch (error) {
      throw new Error(`Error initializing docform: ${ErrorHandlerUtil.getErrorMessage(error)}`);
    }

    this.userList = await this.common.getMyTeamUsers(this.nCaseid);
    this.cdr.detectChanges();
  }

  back() {
    this.OnEvent.emit({ event: DOCFORM_STATIC.eventClose, data: {} });
  }

  async chooseFiles(): Promise<void> {
    if (this.dialogRef) return;
    this.dialogRef = this.dialog.open(FileexplorerComponent, DOCFORM_STATIC.dialog);
    this.dialogRef.componentInstance.nCaseid = this.nCaseid;
    this.dialogRef.componentInstance.isChooser = true;
        this.dialogRef.componentInstance.isLink = DOCFORM_STATIC.isLink;
    this.dialogRef.componentInstance.disabledFiles = this.jFiles.map(a => a.nBundledetailid);
    this.dialogRef.afterClosed().subscribe(result => {
      try {
        const files = this.dialogRef?.componentInstance?.choosedFile ?? [];
        this.jFiles = [...this.jFiles, ...files];
      } catch (error) {
        throw new Error(`chooseFiles.afterClosed error: ${ErrorHandlerUtil.getErrorMessage(error)}`);        
      }
      this.dialogRef = null;
      this.cdr.detectChanges();
    });
  }

  onFilesEvents(e: { type: string }, i: number): void {
    if (e?.type === 'D') {
      this.jFiles.splice(i, 1);
    }
    this.cdr.detectChanges();
  }

  chosenFiles(): unknown[] {
    return this.jFiles.map((a) => ([a.nBundledetailid, a.jLinktype, (a.highlights?.length ? a.highlights : []), (a.texts?.length ? a.texts : [])]));
  }

  async submit(): Promise<void> {
    if (!this.jFiles.length) return;
    if (this.isSubmitted) return;
    this.isSubmitted = true;
    const mdl = {
      nBDid: this.docInfo.nBundledetailid,
      jLT: this.convToStr(this.selectedlinktype),
      jAn: this.convToStr(this.tempAnnots.map(a => a.annots)),
      jDl: this.convToStr(this.chosenFiles()),
      jOT: this.convToStr(this.tempAnnots.map(a => a.text).filter(a => a)),
      jUsers: this.convToStr(this.userList.filter(a => a.isSelected).map(a => a.nUserid)),
      cType: this.annotGlobMode,
    }

    const res = await this.doc.saveDoc(mdl);
    this.isSubmitted = false;
    this.cdr.detectChanges();
    if (res?.msg === 1) {
      this.tost.openSnackBar(res?.value);
          this.OnEvent.emit({ event: DOCFORM_STATIC.eventDocAdded, data: { nDocid: res?.nDocid } });
    } else {
          this.tost.error(DOCFORM_STATIC.errorFactCreation);
    }
  }

  convToStr(val: unknown): string {
    return JSON.stringify(val);
  }
}