import { ChangeDetectionStrategy, ChangeDetectorRef, Component, EventEmitter, Input, OnInit, Output, SimpleChanges } from '@angular/core';
import { CommonModule } from '@angular/common';
import { DocInfo, toolEvents } from '../../../interfaces/pdf.interface';
import { WebService } from '../../../../shared/services/webs/web.service';
import { weblist } from '../../../../shared/interfaces/web.interface';
import { ButtonComponent } from '../../../../shared/components/button/button.component';
import { environment } from '../../../../../environments/environment';
import { IconComponent } from '../../../../shared/components/icon/icon.component';
import { SharedViewComponent } from '../../../../shared/components/shared-view/shared-view.component';
import { SourceCardComponent } from '../../../../shared/components/source-card/source-card.component';
import { TostbarService } from '../../../../core/services/tost/tostbar.service';
import { BadgeComponent } from '../../../../shared/components/badge/badge.component';
import { SecureStorageService } from '../../../../core/services/storage/secure-storage.service';
import { TranslateModule, TranslateService } from '@ngx-translate/core';

@Component({
  selector: 'webdata',
  standalone: true,
  imports: [ButtonComponent, IconComponent, SharedViewComponent, SourceCardComponent, BadgeComponent, TranslateModule, CommonModule],
  changeDetection: ChangeDetectionStrategy.OnPush,
  templateUrl: './webdata.component.html',
  styleUrl: './webdata.component.scss'
})
export class WebdataComponent implements OnInit {

  @Input() docInfo: DocInfo = {} as DocInfo;
  @Input() nCaseid: string;
  @Output() OnEvent = new EventEmitter<toolEvents>();
  @Input() linkIds: string[] = [];
  @Input() userList: any = [];
  @Input() nUserid: string;
  isLoading: boolean = true;
  weblist: weblist[] = [];
  imagepath: any = `${environment.cloudUrl}${environment.downloadpath}`
  constructor(private scureStorage: SecureStorageService, private web: WebService, private cdr: ChangeDetectorRef, private tost: TostbarService, private translate: TranslateService) { }


  async ngOnInit() {
    const res = await this.web.getWebList(this.linkIds);
    if (res && res.length > 0) {
      this.weblist = res[0];
      const users: any = res[1];

      // Create a map for quick lookup of users by web id
      const userMap = new Map<string, any[]>();
      users.forEach(user => {
        if (!userMap.has(user.nWebid)) {
          userMap.set(user.nWebid, []);
        }
        userMap.get(user.nWebid)!.push(user);
      });

      this.weblist.forEach(web => {
        const webUsers = userMap.get(web.nWebid) || [];
        web.shareList = this.userList.map(u => ({
          ...u,
          isSelected: webUsers.some(f => f.nUserid == u.nUserid)
        }));
        web['shareCount'] = webUsers.length;
      });
    }
    this.isLoading = false;
    this.cdr.detectChanges();
  }


  onEvent(e, x) {
    if (e.type == 'UPDATE-USER-COUNT') {
      x.shareCount = e.data;
    }
  }


  async deleteWeb(x) {

    const res = await this.web.deleteWeb(x.nWebid);
    if (res.msg == 1) {
      this.OnEvent.emit({ event: 'DELETE-WEB', data: { nWebid: x.nWebid } });
      this.weblist = this.weblist.filter(a => a.nWebid != x.nWebid);
      if (!this.weblist.length) {
        this.back();
      }
      this.cdr.detectChanges();
      this.tost.success(this.translate.instant('LINKS.WEB_DATA.DELETED_SUCCESS'));
    } else {
      this.tost.error(this.translate.instant('LINKS.WEB_DATA.DELETE_ERROR'));
    }
  }

  openWeb(x) {
    window.open(x.cUrl, '_blank');
  }

  back() {
    this.OnEvent.emit({ event: 'CLOSE', data: {} });
  }



  ngOnChanges(changes: SimpleChanges): void {
    if (changes["linkIds"] && !changes["linkIds"].firstChange) {
      try {
        if (!changes["linkIds"].previousValue.every((value, index) => value === changes["linkIds"].currentValue[index])) {
          this.ngOnInit();
        }
      } catch (error) {
      }
    }
  }


}