  onDateChange(e: string, column: string) {
    this.frm.get('jDate').patchValue({ [column]: e });
  }

  async initData() {
    this.timezoneList = await this.common.getCode(1);
    this.statusList = await this.common.getCode(3);
    this.filetypeList = await this.common.getCode(2);
    this.dateList = await this.common.getCode(16);
    this.userList = await this.common.getMyTeamUsers(this.nCaseid);
    this.bindCurrentTimezone();
  }

  bindCurrentTimezone() {
    const tmzone = Intl.DateTimeFormat().resolvedOptions().timeZone;
    const Tzone = this.timezoneList.find(m => m.jOther.includes(tmzone));
    this.usrtmzone = Tzone;
    if (Tzone) {
      this.frm.patchValue({
        nTZid: Tzone.nValue
      })
    }
  }

  dateTZ(dt) {
    return dt.toLocaleString('sv-SE', { timeZoneName: 'short' });
  }

  async addFactlink() {
    if (this.dialogRef) return;
    this.dialogRef = this.dialog.open(FileexplorerComponent, {
      width: '90vw',
      height: '90vh',
      panelClass: ['rounded-xl', 'overflow-hidden'], // Rounded corners // Enforce rounded corners
      disableClose: true
      // data: {nCaseid:this.nCaseid}
    });
    this.dialogRef.componentInstance.nCaseid = this.nCaseid;
    this.dialogRef.componentInstance.isChooser = true;
    this.dialogRef.componentInstance.isIndividual = true;
    this.dialogRef.componentInstance.isLink = 'F';
    this.dialogRef.componentInstance.disabledFiles = this.jFiles.map(a => a.nBundledetailid);
    this.dialogRef.afterClosed().subscribe(result => {
      try {
        const files = this.dialogRef.componentInstance.choosedFile;
        this.jFiles = [...this.jFiles, ...files];
      } catch (error) {
      }
      this.dialogRef = null;
      this.cdr.detectChanges();
    });
  }


  submitBasicForm() {
    // this.jEditedTexts = [...this.jTexts];
    this.formView = false;
    this.cdr.detectChanges();
  }

  OnFactAassignee(e) {
    if (e.event == 'BACK') {
      this.formView = true;
      this.cdr.detectChanges();
    } else if (e.event == 'SUBMIT') {
      this.finalSubmit(e);
    }
  }

  async lastID(): Promise<number> {
    // Highlight colour follows the LAST issue the user clicked — same spec
    // and same logic as rtFactService.lastID(). Keeps QFact's colour
    // preserved when converting to a full Fact: the QFact stored its colour
    // from selectedIssues[length-1] (last-clicked), the Fact must source it
    // from the same position. The previous getcolorid round-trip returned
    // the server-ranked first row instead — wrong order.
    if (!this.selectedIssues?.length) return 0;
    this.selectedIssues.map(a => a.nIid = a.nIid || a.nIssueid);
    const lastId: any = this.selectedIssues[this.selectedIssues.length - 1]?.nIid;
    return lastId || 0;
  }

  choosenfiles() {
    return this.jFiles.map((a) => ([a.nBundledetailid, a.jLinktype, ((a.highlights && a.highlights.length) ? a.highlights : []), (a.texts ? a.texts : [])]))
  }

  async finalSubmit(e: pdfFinalSubmit) {
    if (!e.issues.length) {
      this.tost.error(this.translate.instant('FACTS.FORM.SELECT_ATLEAST_ONE_ISSUE'));
      return;
    }

    if (this.frm.invalid) return;
    if (this.isSubmitted) {
      return;
    }
    this.isSubmitted = true;
    this.cdr.detectChanges();
    const colorid = await this.lastID();
    let finalMDL: any = {
      nBDid: this.frm.value.nBundledetailid,
      jAn: this.convToStr(this.tempAnnots.map(a => a.annots)),
      nColorid: colorid,
      nFt: this.frm.value.nFiletype,
      nSt: this.frm.value.nStatus,
      jFl: this.convToStr(this.choosenfiles()),
      nTZid: this.frm.value.nTZid,
      jDate: this.convToStr(this.frm.value.jDate),
      jT: this.convToStr(this.jTexts.filter(a => a)),
      jOT: this.convToStr(this.tempAnnots.map(a => a.text).filter(a => a)),
      jIssues: this.convToStr(e.issues.map(a => ([a.nIid, (a.nImpactid ? a.nImpactid : 0), (a.nRelid ? a.nRelid : 0)]))),
      jContacts: this.convToStr(e.contacts.map(a => a.nContactid)),
      jTasks: this.convToStr(e.tasks.map(a => a.nTaskid)),
      jUsers: this.convToStr(e.users.map(a => a.nUserid)),
      cFtype: 'F',
      bIsHighlighted: this.bIsHighlighted,
      cType: this.annotGlobMode,
      jLinktype: this.convToStr(this.selectedlinktype)
    }

    if (this.quickFactDetail) {
      finalMDL.nQFSid = this.quickFactDetail.nFSid;
    }
    const res = await this.factService.saveFact(finalMDL);
    this.isSubmitted = false;
    this.cdr.detectChanges();
    if (res["msg"] == 1) {
      this.tost.openSnackBar(res["value"]);
      this.OnEvent.emit({ event: 'FACT-ADDED', data: { nFSid: res["nFSid"], color: res["color"], colorid: colorid, nQFSid: this.quickFactDetail ? this.quickFactDetail.nFSid : 0 } });
    } else {
      this.tost.error(this.translate.instant('FACTS.FORM.FACT_CREATION_FAILED'));
    }
  }

  convToStr(val: any) {
    return JSON.stringify(val);
  }


  back() {
    this.OnEvent.emit({ event: 'CLOSE', data: {} });
  }

  onValueChanges(e: any, i: number) {

    // this.jTexts[i] = e.target.innerText;
  }
