import { ChangeDetectionStrategy, ChangeDetectorRef, Component, EventEmitter, Input, Output, SimpleChanges } from '@angular/core';
import { factdata, factIssues, factlinkfiles } from '../../../../../shared/interfaces/fact.interface';
import { CommonModule, DatePipe } from '@angular/common';
import { SourceCardComponent } from '../../../../../shared/components/source-card/source-card.component';
import { SelectedIssuesComponent } from '../../../../../shared/components/issues/selected-issues/selected-issues.component';
import { SelectedContactComponent } from '../../../../../shared/components/contacts/selected-contact/selected-contact.component';
import { ButtonComponent } from '../../../../../shared/components/button/button.component';
import { selectedContactList, selectedTaskList } from '../../../../../shared/interfaces/issue.interface';
import { FactService } from '../../../../../shared/services/fact/fact.service';
import { SelectedTasksComponent } from '../../../../../shared/components/tasks/selected-tasks/selected-tasks.component';
import { DocInfo, myTeamUsers } from '../../../../interfaces/pdf.interface';
import { SharedViewComponent } from '../../../../../shared/components/shared-view/shared-view.component';
import { BadgeComponent } from '../../../../../shared/components/badge/badge.component';
import { IconComponent } from '../../../../../shared/components/icon/icon.component';
import { NgxPaginationModule } from 'ngx-pagination';
import { LocationShareComponent } from '../../../../../userpanel/components/location-share/location-share.component';
import { FactboxComponent } from '../../../facts/factbox/factbox.component';
import { QuickPreviewComponent } from '../../../../../userpanel/components/quick-preview/quick-preview.component';
import { TranslateModule } from '@ngx-translate/core';

@Component({
  selector: 'factdetail',
  standalone: true,
  imports: [DatePipe, ButtonComponent, SourceCardComponent, SelectedIssuesComponent, SelectedContactComponent, SelectedTasksComponent, SharedViewComponent,
    CommonModule, BadgeComponent, IconComponent, NgxPaginationModule, LocationShareComponent, FactboxComponent, QuickPreviewComponent, TranslateModule],
  changeDetection: ChangeDetectionStrategy.OnPush,
  templateUrl: './factdetail.component.html',
  styleUrl: './factdetail.component.scss'
})
export class FactdetailComponent {

  @Input() docInfo: DocInfo = {} as DocInfo;

  nCurrent_annot: number = 1;
  @Input() data: factdata = {} as factdata;
  @Input() issueList: factIssues[] = [];
  @Input() filelinks: factlinkfiles[] = [];
  @Input() userList: myTeamUsers[] = [];
  @Input() nUserid: string;
  @Input() nCaseid: string;
  jTexts: string[] = [];
  date1: string;
  date2: string;
  curruntfact: any;

  viewIssue: boolean = true;
  viewlink: boolean = false;
  viewContacts: boolean = false;
  viewTask: boolean = false;
  viewShare: boolean = false;
  selectedContacts: selectedContactList[] = [];
  selectedTasks: selectedTaskList[] = [];
  selectedUsers: myTeamUsers[] = [];
  isContactLoading: boolean = false;
  isTaskLoading: boolean = false;
  isShareLoading: boolean = false;

  @Output() cardevent = new EventEmitter<any>();

  constructor(private cdr: ChangeDetectorRef, private fact: FactService) {

  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes["issueList"] || changes["filelinks"]) {
      this.cdr.detectChanges();
    }
  }

  ngOnInit(): void {
    console.log(this.data);

    this.jTexts = this.data.jTexts || [];
    try {
      if (this.data.jDate) {
        this.date1 = this.data.jDate.date1 || '';
        this.date2 = this.data.jDate.date2 || '';
      }
    } catch (error) {
    }
    this.userList.map(a => a.isSelected = false);
    this.cdr.detectChanges();
  }


  async getContactList() {
    this.viewContacts = !this.viewContacts;

    if (!this.viewContacts) {
      this.cdr.detectChanges();
      return;
    }

    this.isContactLoading = true;
    this.cdr.detectChanges();
    if (this.selectedContacts.length) {
      this.isContactLoading = false;
      this.cdr.detectChanges();
      return;
    }
    this.selectedContacts = await this.fact.getFactContact(this.data.nFSid);

    this.isContactLoading = false;
    this.cdr.detectChanges();

  }

  async getTaskList() {
    this.viewTask = !this.viewTask;

    if (!this.viewTask) {
      this.cdr.detectChanges();
      return;
    }

    this.isTaskLoading = true;
    this.cdr.detectChanges();
    if (this.selectedTasks.length) {
      this.isTaskLoading = false;
      this.cdr.detectChanges();
      return;
    }
    const res: any = await this.fact.getFactTask(this.data.nFSid);
    this.selectedTasks = res[0] || [];
    this.selectedTasks.map(a => {
      var user = [];
      if (res[1]) {
        user = res[1].filter(b => b.jTaskid.includes(a.nTaskid));
      }
      a['teamlist'] = user ? user : [];
    });
    this.selectedTasks.map(a => {
      var remiders = [];
      if (res[2]) {
        let row = res[2].filter(b => b.nTaskid == a.nTaskid);
        remiders = row.length ? row[0].jReminders : [];
      }
      a['jReminders'] = remiders ? remiders : [];
    });

    this.isTaskLoading = false;
    this.cdr.detectChanges();

  }

  onEvent(e) {
    if (e.type == 'UPDATE-USER-COUNT') {
      this.data.t_shared = e.data;
    }
  }

  async getUsers() {
    this.viewShare = !this.viewShare;
    if (!this.viewShare) {
      this.cdr.detectChanges();
      return;
    }

    this.isShareLoading = true;
    this.cdr.detectChanges();
    if (this.selectedUsers.length) {
      this.isShareLoading = false;
      this.cdr.detectChanges();
      return;
    }
    this.selectedUsers = await this.fact.getFactShare(this.data.nFSid);
    this.userList.map(f => f.isSelected = (this.selectedUsers.findIndex(m => m.nUserid == f.nUserid) > -1))

    this.isShareLoading = false;
    this.cdr.detectChanges();

  }

  changePaginatePage(e: any) {
    this.nCurrent_annot = e;
  }


  // selectFactLink(x) {
  //   console.log(x);
  //   if (x.isSelected) {
  //     x.isSelected = false;
  //     this.curruntfact = null;
  //   } else {

  //     this.filelinks.forEach((item) => {
  //       item.isSelected = false;
  //     });
  //     x.isSelected = true;
  //     this.curruntfact = x;
  //   }
  // }


  selectFactLink(x: any) {

    this.curruntfact = x;

    // this.cardevent.emit({ event: 'OPEN-FACT-LINK', data: x });
  }


  OnQuickPreviewEvent(e: any) {
    if (e.event == 'OPEN-FILE') {
      this.cardevent.emit({ event: 'OPEN-FACT-LINK', data: e.data });
    }
  }


}
