  ngOnChanges(changes: SimpleChanges): void {
    //Called before any other lifecycle hook. Use it to inject dependencies, but avoid any serious work here.
    //Add '${implements OnChanges}' to the class.
    if (changes['linkIds'] && !changes['linkIds'].firstChange) {
      this.getDetail();
    }
    this.cdr.detectChanges();
  }

  async getDetail() {
    const nUserid = await this.storage.getUserId();
    const factlist = await this.factService.getFactDetails(this.linkIds);
    if (!factlist.length) {
      this.tost.error(this.translate.instant('FACTS.QUICK.NO_DATA_FOUND'));
    }
    const res = await this.factService.getFactIssuesAndLinks(this.linkIds);
    if (res.length) {
      const issues: factIssues[] = res[0] || [];
      factlist.map(a => a.issueList = issues.filter(b => b.nFSid == a.nFSid).map((d, index) => { return { ...d, nSerial: index + 1 } }));
      const fsValue = window.localStorage.getItem('editQF');
      if (fsValue) {
        const index = factlist.findIndex(a => a.nFSid == fsValue);
        if (factlist[0]?.nUserid == nUserid) {
          this.quickFactDetail = factlist[index]
          this.selectedIssues = [];
          window.localStorage.removeItem('editQF');
        }
      }
    }

    try {
      // if (this.factlist[0]["cIsNote"] != 'Y') {
      const jTexts = factlist[0]["jTexts"] || [];
      const finalList = jTexts.filter(a => a.trim() != '');
      // if (!finalList?.length)
      if (factlist[0]?.nUserid == nUserid) {
        this.selectedIssues = [];
        this.quickFactDetail = factlist[0]
      }
      // }
    } catch (error) {

    }
    this.ngOnInit();
  }
