  createIssue(x?) {
    this.expandIssue = false;
    const dialog = this.dialog.open(CreateissueComponent, {
      width: '440px',
      height: 'calc(100% - 56px)',
      hasBackdrop: false,
      panelClass: ['noshadow', 'norounded'],
      position: {
        top: `56px`,
        right: `0px`,
      },
      data: { type: x ? 'E' : null, value: x ? x : null, current_session: { nCaseid: this.nCaseid } },
    });
    dialog.afterClosed().subscribe((result) => {
      this.expandIssue = true;
      this.cdr.detectChanges();
    })
  }

  async lastID(): Promise<number> {
    // Highlight colour follows the LAST issue the user clicked — same spec
    // and same logic as rtFactService.lastID(). The previous getcolorid
    // round-trip returned the server-ranked first row, which produced the
    // FIRST-selected issue's colour — wrong order.
    if (!this.selectedIssues?.length) return 0;
    this.selectedIssues.map(a => a.nIid = a.nIid || a.nIssueid);
    const lastId: any = this.selectedIssues[this.selectedIssues.length - 1]?.nIid;
    return lastId || 0;
  }


  async submit() {
    if (!this.selectedIssues.length) return;
    if (this.isSubmitted) {
      return;
    }
    this.isSubmitted = true;
    this.cdr.detectChanges();
    const colorid = await this.lastID();
    const jLinktype: any = this.convToStr(this.selectedlinktype)
    const jContacts = this.convToStr([...new Set(this.selectedContacts.map(a => a.nContactid))]);
    if (this.cPermission == 'N') {
      /*    const finalMDL = {
            nBDid: this.docInfo.nBundledetailid,
            jAn: this.convToStr(this.tempAnnots.map(a => a.annots)),
            nColorid: colorid,
            jT: this.convToStr(this.jTexts.filter(a => a)),
            jOT: this.convToStr(this.tempAnnots.map(a => a.text).filter(a => a)),
            jIssues: this.convToStr(this.selectedIssues.map(a => ([a.nIid, (a.nImpactid ? a.nImpactid : 0), (a.nRelid ? a.nRelid : 0)]))),
            cFtype: 'QF',
          }
          const res = await this.factService.saveQuickFact(finalMDL);
    */

      const { res } = await this.factService.submitQuickFact(this.selectedIssues, this.docInfo, this.jTexts, this.tempAnnots, this.isNoteEdited, jLinktype, jContacts);
      this.isSubmitted = false;
      this.cdr.detectChanges();
      if (res["msg"] == 1) {
        this.tost.openSnackBar(res["value"]);
        this.OnEvent.emit({ event: 'QUICK-FACT-ADDED', data: { nFSid: res["nFSid"], color: res["color"], colorid: colorid } });
      } else {
        this.tost.error(this.translate.instant('FACTS.QUICK.CREATION_FAILED'));
      }
    } else {
      const mdl = {
        nFSid: this.quickFactDetail.nFSid,
        nColorid: colorid,
        jTexts: this.convToStr(this.jTexts.filter(a => a)),
        jIssue: this.convToStr(this.selectedIssues.map(a => ([a.nIssueid || a.nIid, a.nImpactid || 0, (a.nRelid || a.nRelevanceid) || 0]))),
        cIsNote: 'N', //this.isNoteEdited ? 'N' : 'N'
        jContacts
      };
      const res = await this.factService.updateQuickFacts(mdl);
      this.cdr.detectChanges();
      if (res.msg == 1) {
        this.cPermission = "N";
        this.tost.success(res.value);
        this.OnEvent.emit({ event: 'QUICK-FACT-UPDATED', data: { nFSid: res["nFSid"], color: res["color"], colorid: colorid } });
        this.back();
      } else {
        this.tost.error(res.value);
      }
    }
  }

  convToStr(val: any) {
    return JSON.stringify(val);
  }

  async deleteqfact() {
    const res = await this.factService.deleteFact(this.quickFactDetail.nFSid);
    if (res && res.msg == 1) {
      if (this.quickFactDetail.nFSid) {
        this.cdr.detectChanges();
        this.OnEvent.emit({ event: 'DELETE-FACT', data: { nFSid: this.quickFactDetail.nFSid, total: 0 } });
        this.back();
      }
    } else {
      this.tost.error(`${res.value}`);
    }
  }

  convertToFullFact() {
    this.OnEvent.emit({ event: 'CONVERT-TO-FACT', data: this.quickFactDetail });
  }


  textchange(ev) {
    this.haschange = true;
  }

  issueevent(ev) {
    if (ev.event = 'ISSUE_CHNAGE') {
      this.haschange = true;
    }
  }



  getButtonText(): string {
    if (this.cPermission == 'N') {
      return this.translate.instant('FACTS.QUICK.CREATE_Q_FACT');
    } else if (this.cPermission == 'E' && !this.haschange) {
      return this.translate.instant('FACTS.QUICK.UPDATED');
    } else if (this.cPermission == 'E' && this.haschange) {
      return this.translate.instant('FACTS.QUICK.UPDATE');
    }
    return '';
  }

  emitFactNote(event) {
    if (event.event == 'ADD-CONTECT') {
      this.selectedContacts.push(event.data.original)
      this.selectedContactsChange.emit(this.selectedContacts)
    }
  }

