  constructor(private navigateService: NavigateService, private cdr: ChangeDetectorRef) { }

  async ngOnInit() {
    
    if (this.onNavigateEvent) {
      this.onNavigateEvent.subscribe((e: toolEvents) => {
        if (e.event == 'FILTER') {
          this.jFilter = e.data;
          this.initList()
        }
      });
    }
    this.initList();
  }

  async initList() {
    let res;
    if (this.mode == 'TFC') {
      res = await this.navigateService.getFactTaskLists(this.docInfo.nBundledetailid, 'H', 'D', 1, this.jFilter);

    } else {
      res = await this.navigateService.getFileTaskLists(this.docInfo.nBundledetailid, 'H', 'D', 1, this.jFilter);
    }
    // const res = await this.navigateService.getFactTaskLists(this.docInfo.nBundledetailid, 'H', 'D', 1);
    if (res.length) {
      const tasklist: navigateTaskList[] = res[0];
      this.noOfRecord.emit(tasklist.length);
      const sharedList = res[1] || [];
      const issueList = res[2] || [];
      tasklist.forEach(e => {
        e.userList = sharedList.filter((s) => s.jTaskids.includes(e.nTaskid));
        e.issueList = issueList.filter((s) => s.jTaskids.includes(e.nTaskid));
      });
      this.tasklist.push(...res[0]);
    }
    this.cdr.detectChanges();
  }

  async getCardEvent(e: any, i: number) {
    
    if (this.nTaskid == e.x.nTaskid && this.type == e.data) {
      this.nTaskid = null;
      this.type = '';
    } else {
      this.nTaskid = e.x.nTaskid;
      this.type = e.data;
    }
    if (e.event == 'VIEW') {
      // this.OnEvent.emit(e);
      this.OnEvent.next(e);
    }
  }
