import { Component, EventEmitter, Input, Output, ViewChild } from '@angular/core';
import { ButtonComponent } from '../../button/button.component';
import { IconComponent } from '../../icon/icon.component';
import { CommonModule } from '@angular/common';
import { IssueslistComponent } from '../issueslist/issueslist.component';
import { CreateissueComponent } from '../../../../realtime/components/issues/createissue/createissue.component';
import { MatDialog } from '@angular/material/dialog';
import { TostbarService } from '../../../../core/services/tost/tostbar.service';
import { IssueService } from '../../../../realtime/services/issue/issue.service';
import { IssuedetailComponent } from '../issuedetail/issuedetail.component';
import { IssueListComponent } from '../../../../realtime/components/issues/issue-list/issue-list.component';

@Component({
  selector: 'app-issuedialog',
  standalone: true,
  imports: [ButtonComponent, IconComponent, IssueslistComponent, CommonModule, IssuedetailComponent],
  templateUrl: './issuedialog.component.html',
  styleUrl: './issuedialog.component.scss'
})
export class IssuedialogComponent {
  issuedetail: boolean = false;
  @Input() nCaseid: string;
  @Output() OnEvent = new EventEmitter<any>();
  @ViewChild('issueListC') issueListC: IssueListComponent;
  currentdetail: any;

  constructor(private dialog: MatDialog, public issue: IssueService, private tost: TostbarService) { }

  close() {
    this.OnEvent.emit({ event: 'CLOSE', data: {} });
  }


  createIssue(x?) {
    const dialog = this.dialog.open(CreateissueComponent, {
      width: '440px',
      height: 'calc(100% - 56px)',
      hasBackdrop: false,
      panelClass: ['noshadow', 'norounded'],
      position: {
        top: `56px`,
        right: `0px`,
      },
      data: { type: x ? 'E' : null, value: x ? x : null, current_session: { nCaseid: this.nCaseid } },
    });
    dialog.afterClosed().subscribe((result) => {
      if (this.issueListC) {
        this.issueListC.ngOnInit();
      }
      if (result) {
        if (result.isDeleted) {
          this.OnEvent.emit({ event: 'ISSUE-DELETED', data: { nIid: x.nIid } });
        }
        else {
          this.OnEvent.emit({ event: 'ISSUE-UPDATED', data: { nIid: x.nIid } });
        }
      }
    })
  }



  clickevnt(ev) {
    if (ev.type == 'edit') {
      this.createIssue(ev.data);
    }
    if (ev.type == 'delete') {
      this.deleteIssue(ev.data);
    }
    if (ev.type == 'detail') {
      // this.issuedetail = true;
      // this.currentdetail = ev.data;
    }
    if (ev.event == 'FILTER-ISSUE-DETAIL') {
      this.OnEvent.emit(ev);
    }
  }

  deleteIssue(x) {

    this.issue.issueDelete(x.nIid).then((res) => {
      if (res[0]["msg"] == 1) {
        this.tost.openSnackBar('Issue deleted successfully', '');
        if (this.issueListC) {
          this.issueListC.ngOnInit();
          this.OnEvent.emit({ event: 'ISSUE-DELETED', data: { nIid: x.nIid } });
        }
      } else {
        this.tost.openSnackBar(res[0]["message"], 'E');
      }
    })
  }

  issueDetailEvent(ev) {
    this.issuedetail = false;
  }

}
