import { ChangeDetectionStrategy, ChangeDetectorRef, Component, EventEmitter, Input, OnInit, Output, SimpleChanges } from '@angular/core';
import { CommonModule } from '@angular/common';
import { DocInfo, toolEvents } from '../../../interfaces/pdf.interface';
import { IconComponent } from '../../../../shared/components/icon/icon.component';
import { DocService } from '../../../../shared/services/docs/doc.service';
import { doclist } from '../../../../shared/interfaces/doc.interface';
import { SourceCardComponent } from '../../../../shared/components/source-card/source-card.component';
import { SharedViewComponent } from '../../../../shared/components/shared-view/shared-view.component';
import { TostbarService } from '../../../../core/services/tost/tostbar.service';
import { BadgeComponent } from '../../../../shared/components/badge/badge.component';
import { NgxPaginationModule } from 'ngx-pagination';
import { QuickPreviewComponent } from '../../../../userpanel/components/quick-preview/quick-preview.component';

import { TranslateModule, TranslateService } from '@ngx-translate/core';

@Component({
  selector: 'docdata',
  standalone: true,
  imports: [IconComponent, SourceCardComponent, SharedViewComponent, BadgeComponent, NgxPaginationModule, QuickPreviewComponent, TranslateModule, CommonModule],
  changeDetection: ChangeDetectionStrategy.OnPush,
  templateUrl: './docdata.component.html',
  styleUrl: './docdata.component.scss'
})

export class DocdataComponent implements OnInit {
  nCurrent_annot: number = 1;
  @Input() docInfo: DocInfo = {} as DocInfo;
  @Input() nCaseid: string;
  @Input() fullMode: boolean = false;
  @Output() OnEvent = new EventEmitter<toolEvents>();
  @Input() linkIds: string[] = [];
  @Input() userList: any = [];
  @Input() nUserid: string;
  isLoading: boolean = true;
  docdetail: any;
  docList: doclist[] = [];
  constructor(private doc: DocService, private cdr: ChangeDetectorRef, private tost: TostbarService, private translate: TranslateService) { }

  back() {
    this.OnEvent.emit({ event: 'CLOSE', data: {} });
  }

  async ngOnInit() {

    const res = await this.doc.getDocList(this.linkIds);
    if (res && res.length > 0) {
      this.docList = res[0];
      const files: any = res[1] || [];
      const users: any = res[2] || [];

      // Create a map for quick file lookups
      const filesMap = files.reduce((map, file) => {
        if (!map[file.nDocid]) map[file.nDocid] = [];
        map[file.nDocid].push(file);
        return map;
      }, {} as Record<number, any[]>);

      // Create a map for quick user lookups by doc id
      const userDocMap = new Map<string, Set<string>>();
      users.forEach(user => {
        user.docids.forEach(docId => {
          if (!userDocMap.has(docId)) {
            userDocMap.set(docId, new Set<string>());
          }
          userDocMap.get(docId)!.add(user.nUserid);
        });
      });

      this.docList.forEach(doc => {
        doc.files = filesMap[doc.nDocid] || [];
        doc.shareList = this.userList.map(u => ({
          ...u,
          isSelected: userDocMap.get(doc.nDocid)?.has(u.nUserid) || false
        }));
        doc['shareCount'] = doc.shareList.filter(user => user.isSelected).length;
      });

      console.log('docList', this.docList);


      this.cdr.detectChanges();
    }
  }


  onEvent(e, x) {
    if (e.type == 'UPDATE-USER-COUNT') {
      x['shareCount'] = e.data;
    }
  }

  linkedEvents(e, l, x) {
    if (e.type == 'D') {
      this.deleteLink(l, x);
    }
    if (e.type == 'V') {
      this.selctdoclink(l, x.files);
    }
    if (e.type == 'OPEN-DOC-LINK') {
      this.docdetail = l;
      // this.OnEvent.emit({ event: e.type, data: l });
    }
  }


  async deleteLink(l, x) {
    const res = await this.doc.deleteDoc(x.nDocid, l.nDMLids);
    if (res.msg == 1) {
      this.tost.openSnackBar(this.translate.instant('LINKS.DOC_DATA.DELETED_SUCCESS'));
      const ind = x.files.findIndex(a => a.nDMLids == l.nDMLids);
      if (ind > -1) {
        x.files.splice(ind, 1);
      }
      if (!x.files.length) {
        const ind = this.docList.findIndex(a => a.nDocid == x.nDocid);
        if (ind > -1) {
          this.docList.splice(ind, 1);
          this.OnEvent.emit({ event: 'DELETE-DOC', data: { nDocid: x.nDocid } });
        }
      }
      if (!this.docList.length) {
        this.back();
      }
    } else {
      this.tost.error(res.value);
    }
    this.cdr.detectChanges();
  }



  changePaginatePage(e: any) {
    this.nCurrent_annot = e;
  }

  selctdoclink(x, list) {
    console.log(x);
    if (x.isSelected) {
      x.isSelected = false;
      this.docdetail = null;
    } else {

      list.forEach((item) => {
        item.isSelected = false;
      });
      x.isSelected = true;
      this.docdetail = x;
    }
  }




  ngOnChanges(changes: SimpleChanges): void {
    if (changes["linkIds"] && !changes["linkIds"].firstChange) {
      try {
        if (!changes["linkIds"].previousValue.every((value, index) => value === changes["linkIds"].currentValue[index])) {
          this.ngOnInit();
        }
      } catch (error) {
      }
    }
  }

  OnQuickPreviewEvent(e) {
    this.OnEvent.emit({ event: 'OPEN-DOC-LINK', data: e.data });
  }


}