import { CommonModule } from '@angular/common';
import { ChangeDetectionStrategy, ChangeDetectorRef, Component, EventEmitter, Input, Output } from '@angular/core';
import { IconComponent } from '../../icon/icon.component';
import { ButtonComponent } from '../../button/button.component';
import { MatMenuModule } from '@angular/material/menu';
import { issueList } from '../../../interfaces/issue.interface';
import { IssueService } from '../../../services/issues/issue.service';

@Component({
  selector: 'issueslist',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.Default,
  imports: [CommonModule, IconComponent, ButtonComponent, MatMenuModule],
  templateUrl: './issueslist.component.html',
  styleUrl: './issueslist.component.scss'
})
export class IssueslistComponent {
  isLoading: boolean = true;
  @Input() nCaseid: string;
  @Output() clickEvent = new EventEmitter<any>();
  issueList: issueList[] = [];

  constructor(private issueService: IssueService, private cdr: ChangeDetectorRef) {

  }

  async ngOnInit() {
    this.issueList = await this.issueService.fetchIssueList(this.nCaseid);
    this.isLoading = false;
    this.cdr.detectChanges();
  }


  deleteIssue(x) {
    this.clickEvent.emit({ type: 'delete', data: x });
  }

  detail(x) {
    this.clickEvent.emit({ event: 'FILTER-ISSUE-DETAIL', data: x });
  }

  edit(x) {
    this.clickEvent.emit({ type: 'edit', data: x });
  }
}
