import { ChangeDetectorRef, Component, EventEmitter, Input, Output, SimpleChanges } from '@angular/core';
import { IssueDetail, LinkDetail, navigateModeType } from '../../../interfaces/navigate.interface';
import { myTeamUsers, toolEvents } from '../../../../pdf/interfaces/pdf.interface';
import { NavigateService } from '../../../services/navigate/navigate.service';
import { Subject } from 'rxjs';
import { FactcardComponent } from '../../../../pdf/components/linkviews/facts/factcard/factcard.component';

@Component({
  selector: 'app-qfact',
  standalone: true,
  imports: [FactcardComponent],
  templateUrl: './qfact.component.html',
  styleUrl: './qfact.component.scss'
})
export class QfactComponent {

  @Input() docInfo: any = {};
  @Input() nBundledetailid: string = null;
  @Input() userList: myTeamUsers[] = [];
  factlist: any = [];
  @Output() noOfRecord: EventEmitter<number> = new EventEmitter();
  @Output() OnEvent: EventEmitter<any> = new EventEmitter();
  @Input() onNavigateEvent: Subject<toolEvents>;
  jFilter: any[] = [];
  @Input() selectedMode: navigateModeType;
  @Input() nViewissueid: number = 0;
  @Input() viewmode: string = 'M';
  nFSid: string;
  type: string;

  @Input() sortBy: string = 'desc';

  constructor(private navigateService: NavigateService, private cdr: ChangeDetectorRef) { }


  ngOnInit(): void {
    if (this.nViewissueid) {
      this.jFilter = [{ "name": "ISSUE", "type": "V", "value": [this.nViewissueid] }];
    }
    this.getFactList(1);

    if (this.onNavigateEvent) {
      this.onNavigateEvent.subscribe((e: toolEvents) => {

        if (e.event == 'FILTER' && this.selectedMode == 'QF') {

          this.jFilter = e.data;
          this.getFactList(1);
        }
      });
    }

  }

  async getFactList(pageNo) {
    let res: any = await this.navigateService.getFactlist(this.docInfo.nBundledetailid, 'H', this.sortBy, pageNo, this.jFilter, 'QF') || [];
    // if (pageNo > 1) {
    //   this.factlist = [...this.factlist, ...res[0]];
    // } else {
    this.factlist = res && res.length ? res[0] : [];
    // }
    this.noOfRecord.emit(this.factlist.length);
    let IssueDetail: IssueDetail[] = res[1] || [];
    let LinkDetail: LinkDetail[] = res[2] || [];
    try {
      this.factlist.forEach(element => {
        element.issueList = IssueDetail.filter(x => x.jFSids.includes(element.nFSid));
        element.linkfile = LinkDetail.filter(x => x.nFSid == element.nFSid);
      })
    } catch (error) {

    }

    this.cdr.detectChanges();
  }

  async getCardEvent(e: any, x, i: number) {
    if (this.type == e.data && this.nFSid == x.nFSid) {
      this.nFSid = null;
      this.type = '';
    } else {
      this.nFSid = x.nFSid;
      this.type = e.data;
    }
    if (e.event == 'VIEW') {
      e.x = x;
      this.OnEvent.next(e);
    }
    this.cdr.detectChanges();
  }


  OnViewEvent(x) {
    this.OnEvent.next({
      event: 'VIEW-DETAIL-LINKS',
      data: {
        id: x.nFSid,jLinktype: x.jLinktype,
        type: 'QF'
      }
    });
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes && changes['sortBy'] && !changes['sortBy'].firstChange) {
      this.getFactList(1);
    }
  }
}
