import { HttpClient, HttpParams } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { environment } from '../../../../environments/environment';

@Injectable({
  providedIn: 'root'
})
export class DocService {

  constructor(private http: HttpClient) { }

  async saveDoc(mdl): Promise<any> {
    try {
      const res: any = await firstValueFrom(
        this.http.post<any>(`${environment.cloudUrl}${environment.coreservice}/doclink/insertdoc`, mdl)
      );
      if (res && res.msg == 1) {
        return res;
      } else {
        return res;
      }
    } catch (err) {
      return { msg: -1, error: err, value: '' };
    }
  }





  async getDocList(jDocids: string[]): Promise<any[]> {
    const params = new HttpParams().set('jDocids', JSON.stringify(jDocids));
    let res: any = [];
    try {
      res = await firstValueFrom(
        this.http.get<any[]>(
          `${environment.cloudUrl}${environment.coreservice}/doclink/docdetail`, { params: params }
        )
      );
    } catch (error) {
      console.error(error)
      res = [];
    }
    return res;
  }

  async deleteDoc(nDocid, nDMLids): Promise<any> {
    try {
      const res: any = await firstValueFrom(
        this.http.post<any>(`${environment.cloudUrl}${environment.coreservice}/doclink/docdelete`, { nDocid: nDocid, nDMLids: nDMLids })
      );
      return res[0];
    } catch (err) {
      return { msg: -1, error: err, value: 'Failed to delete' };
    }
  }

}
