import { ChangeDetectionStrategy, ChangeDetectorRef, Component, EventEmitter, Input, OnInit, Output, SimpleChanges } from '@angular/core';
import { IconComponent } from '../../../../../shared/components/icon/icon.component';
import { ButtonComponent } from '../../../../../shared/components/button/button.component';
import { SourceCardComponent } from '../../../../../shared/components/source-card/source-card.component';
import { FactcardComponent } from '../../../../../pdf/components/linkviews/facts/factcard/factcard.component';
import { NavigateService } from '../../../../services/navigate/navigate.service';
import { navigateModeType, navigateWeblist } from '../../../../interfaces/navigate.interface';
import { environment } from '../../../../../../environments/environment';
import { toolEvents } from '../../../../../pdf/interfaces/pdf.interface';
import { Subject } from 'rxjs';
import { finalFilterList } from '../../../../../shared/interfaces/filter.interface';
import { SharedViewComponent } from '../../../../../shared/components/shared-view/shared-view.component';
import { WebcardComponent } from '../../webcard/webcard.component';

@Component({
  selector: 'app-web-link',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [WebcardComponent],
  templateUrl: './web-link.component.html',
  styleUrl: './web-link.component.scss'
})
export class WebLinkComponent implements OnInit {
  @Input() viewmode: string;
  @Input() docInfo: any = {};
  @Input() nBundledetailid: string = null;
  @Output() noOfRecord: EventEmitter<number> = new EventEmitter();

  weblist: navigateWeblist[] = [];

  imagepath: any = `${environment.cloudUrl}${environment.downloadpath}`
  @Output() OnEvent: EventEmitter<any> = new EventEmitter();
  @Input() selectedMode: navigateModeType;
  jFilter: finalFilterList[] = [];
  @Input() onNavigateEvent: Subject<toolEvents>;
  @Input() userList: any = [];
  @Input() nCaseid: string;
  @Input() sortBy: string = 'desc';

  constructor(private navigateService: NavigateService, private cdr: ChangeDetectorRef) { }


  async ngOnInit() {

    if (this.onNavigateEvent) {
      this.onNavigateEvent.subscribe((e: toolEvents) => {
        if (e.event == 'FILTER') {
          this.jFilter = e.data;
          this.initList()
        }
      });
    }
    this.initList()
  }

  async initList() {
    this.weblist = await this.navigateService.getWebLinkLists(this.nBundledetailid, 'H', this.sortBy, 1, this.jFilter);
    this.noOfRecord.emit(this.weblist.length);
    this.cdr.detectChanges();
  }

  OnViewEvent(x) {
    this.OnEvent.next({
      event: 'VIEW-DETAIL-LINKS',
      data: {
        id: x.nWebid,
        type: 'W'
      }
    });
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes && changes['sortBy'] && !changes['sortBy'].firstChange) {
      this.initList();
    }
  }
}
