import { ChangeDetectionStrategy, ChangeDetectorRef, Component, EventEmitter, Input, Output, SimpleChanges } from '@angular/core';
import { IconComponent } from '../../../../../shared/components/icon/icon.component';
import { ButtonComponent } from '../../../../../shared/components/button/button.component';
import { SourceCardComponent } from '../../../../../shared/components/source-card/source-card.component';
import { FactcardComponent } from '../../../../../pdf/components/linkviews/facts/factcard/factcard.component';
import { NavigateService } from '../../../../services/navigate/navigate.service';
import { FactCompanyRes, IssueDetail, LinkDetail, navigateModeType } from '../../../../interfaces/navigate.interface';
import { myTeamUsers, toolEvents } from '../../../../../pdf/interfaces/pdf.interface';
import { CommonModule } from '@angular/common';
import { Subject } from 'rxjs';
import { finalFilterList } from '../../../../../shared/interfaces/filter.interface';

@Component({
  selector: 'app-fact-contact',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [IconComponent, ButtonComponent, SourceCardComponent, FactcardComponent, CommonModule],
  templateUrl: './fact-contact.component.html',
  styleUrl: './fact-contact.component.scss'
})
export class FactContactComponent {

  @Input() docInfo: any = {};
  @Input() nBundledetailid: string = null;
  companylist: any = [];
  @Output() noOfRecord: EventEmitter<number> = new EventEmitter();
  @Input() userList: myTeamUsers[] = [];
  @Output() OnEvent: EventEmitter<any> = new EventEmitter();
  @Input() onNavigateEvent: Subject<toolEvents>;
  jFilter: finalFilterList[] = [];
  @Input() selectedMode: navigateModeType;
  @Input() viewmode: string = 'M';
  nFSid: string;
  type: string
  @Input() sortBy: string = 'desc';
  constructor(private navigateService: NavigateService, private cdr: ChangeDetectorRef) { }


  ngOnInit(): void {
    //Called after the constructor, initializing input properties, and the first call to ngOnChanges.
    //Add 'implements OnInit' to the class.
    this.getCompanylist();



    if (this.onNavigateEvent) {
      this.onNavigateEvent.subscribe((e: toolEvents) => {
        if (e.event == 'FILTER' && this.selectedMode == 'FCO') {
          this.jFilter = e.data;
          if (this.companylist?.length) {
            this.getCompFactList(this.companylist[0] || {});
          }
        }
      });
    }

  }



  async getCompanylist() {

    let res: FactCompanyRes[] = await this.navigateService.getCompanylist(this.nBundledetailid);
    this.companylist = res || [];
    this.noOfRecord.emit(this.companylist.length);
    if (this.companylist?.length) {
      this.getCompFactList(res[0] || {});
    }
    this.cdr.detectChanges();

  }


  async getCompFactList(x) {

    if (x['expand']) { x['expand'] = false; return; };
    let res: any = await this.navigateService.getCompanyFactlist(x.nCompanyid, this.nBundledetailid, this.jFilter, this.sortBy);
    if (!res.length) return;
    let factlist = res[0];
    let IssueDetail: IssueDetail[] = res[1];
    let LinkDetail: LinkDetail[] = res[2];
    factlist.forEach(element => {
      element.issueList = IssueDetail.filter(x => x.jFSids.includes(element.nFSid));
      element.linkfile = LinkDetail.filter(x => x.nFSid == element.nFSid);
    })
    x.expand = true;
    x.factlist = factlist;
    this.cdr.detectChanges();
  }

  async getCardEvent(e: any, x, i: number) {
    if (this.type == e.data && this.nFSid == x.nFSid) {
      this.nFSid = null;
      this.type = '';
    } else {
      this.nFSid = x.nFSid;
      this.type = e.data;
    }
    if (e.event == 'VIEW') {
      e.x = x;
      this.OnEvent.next(e);
    }
    this.cdr.detectChanges();
  }

  OnViewEvent(x) {
    this.OnEvent.next({
      event: 'VIEW-DETAIL-LINKS',
      data: {
        id: x.nFSid,
        jLinktype: x.jLinktype,
        type: 'F'
      }
    });
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes && changes['sortBy'] && !changes['sortBy'].firstChange) {
      this.getCompanylist();
    }
  }
}

