import { HttpClient, HttpParams } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { environment } from '../../../../environments/environment';
import { weblist } from '../../interfaces/web.interface';

@Injectable({
  providedIn: 'root'
})
export class WebService {

  constructor(private http: HttpClient) { }


  async getUrlData(url: string, nCaseid: string): Promise<any> {
    let params = new HttpParams().set('nCaseid', nCaseid);
    params = params.set('url', url);
    let res: any = [];
    try {
      res = await firstValueFrom(
        this.http.get<any>(
          `${environment.cloudUrl}${environment.coreservice}/weblink/getwebdata`, { params: params }
        )
      );
    } catch (error) {
      console.error(error)
      res = [];
    }
    return res;
  }



  async saveWeb(mdl): Promise<any> {
    try {
      const res: any = await firstValueFrom(
        this.http.post<any>(`${environment.cloudUrl}${environment.coreservice}/weblink/insertweb`, mdl)
      );
      if (res && res.msg == 1) {
        return res;
      } else {
        return res;
      }
    } catch (err) {
      return { msg: -1, error: err, value: '' };
    }
  }






  async getWebList(jWebids: string[]): Promise<any[]> {
    const params = new HttpParams().set('jWebids', JSON.stringify(jWebids));
    let res: any = [];
    try {
      res = await firstValueFrom(
        this.http.get<any[]>(
          `${environment.cloudUrl}${environment.coreservice}/weblink/getweblinklist`, { params: params }
        )
      );
    } catch (error) {
      console.error(error)
      res = [];
    }
    return res;
  }


  async deleteWeb(nWebid: string) {
    try {
      const res: any = await firstValueFrom(
        this.http.post<any>(`${environment.cloudUrl}${environment.coreservice}/weblink/deleteweb`, { nWebid: nWebid })
      );
      return res;
    } catch (err) {
      return { msg: -1, error: err, value: '' };
    }
  }


}
