import { ChangeDetectionStrategy, ChangeDetectorRef, Component, EventEmitter, Input, OnInit, Output, SimpleChanges } from '@angular/core';
import { DocInfo, toolEvents } from '../../../../interfaces/pdf.interface';
import { factdata, factIssues } from '../../../../../shared/interfaces/fact.interface';
import { FactService } from '../../../../../shared/services/fact/fact.service';
import { TostbarService } from '../../../../../core/services/tost/tostbar.service';
import { IconComponent } from '../../../../../shared/components/icon/icon.component';
import { SourceCardComponent } from '../../../../../shared/components/source-card/source-card.component';
import { FactcardComponent } from '../factcard/factcard.component';
import { ButtonComponent } from '../../../../../shared/components/button/button.component';
import { CommonModule } from '@angular/common';
import { BadgeComponent } from '../../../../../shared/components/badge/badge.component';
import { SecureStorageService } from '../../../../../core/services/storage/secure-storage.service';
import { TranslateModule, TranslateService } from '@ngx-translate/core';

@Component({
  selector: 'quickfactdata',
  standalone: true,
  imports: [IconComponent, SourceCardComponent, FactcardComponent, ButtonComponent, CommonModule, BadgeComponent, TranslateModule],
  changeDetection: ChangeDetectionStrategy.OnPush,
  templateUrl: './quickfactdata.component.html',
  styleUrl: './quickfactdata.component.scss'
})
export class QuickfactdataComponent implements OnInit {
  @Input() docInfo: DocInfo = {} as DocInfo;
  @Input() nCaseid: string;
  @Output() OnEvent = new EventEmitter<toolEvents>();
  @Input() linkIds: string[] = [];
  isLoading: boolean = true;

  factlist: factdata[] = [];
  nUserid: string | null = null;
  constructor(private factService: FactService, private cdr: ChangeDetectorRef, private tost: TostbarService,
    private storage: SecureStorageService, private translate: TranslateService
  ) {

  }

  async ngOnInit() {

    this.nUserid = await this.storage.getUserId();
    this.factlist = await this.factService.getFactDetails(this.linkIds);
    if (!this.factlist.length) {
      this.isLoading = false;
      this.tost.error(this.translate.instant('FACTS.QUICK.NO_DATA_FOUND'));
    }
    this.isLoading = false;
    try {
      if (this.factlist.length > 0) {

        const res = await this.factService.getFactIssuesAndLinks(this.linkIds);
        if (res.length) {
          const issues: factIssues[] = res[0] || [];
          this.factlist.map(a => a.issueList = issues.filter(b => b.nFSid == a.nFSid).map((d, index) => { return { ...d, nSerial: index + 1 } }));
          const fsValue = window.localStorage.getItem('editQF');
          if (fsValue) {
            const index = this.factlist.findIndex(a => a.nFSid == fsValue);
            if (this.factlist[0]?.nUserid == this.nUserid) {
              this.edit(this.factlist[index]);
              window.localStorage.removeItem('editQF');
            }
          }
        }

        try {
          // if (this.factlist[0]["cIsNote"] != 'Y') {
          const jTexts = this.factlist[0]["jTexts"] || [];
          const finalList = jTexts.filter(a => a.trim() != '');
          // if (!finalList?.length)
          if (this.factlist[0]?.nUserid == this.nUserid) {
            this.edit(this.factlist[0]);
          }
          // }
        } catch (error) {

        }
        this.cdr.detectChanges();
      } else {
        this.cdr.detectChanges();
      }
    } catch (error) {

    }

    this.cdr.detectChanges();
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes["linkIds"] && !changes["linkIds"].firstChange) {
      try {
        if (!changes["linkIds"].previousValue.every((value, index) => value === changes["linkIds"].currentValue[index])) {
          this.ngOnInit();
        }
      } catch (error) {
      }
    }
  }

  async deleteqfact(x, i) {
    const res = await this.factService.deleteFact(x.nFSid);
    if (res && res.msg == 1) {
      if (x.nFSid) {
        this.factlist.splice(i, 1);
        this.cdr.detectChanges();
        this.OnEvent.emit({ event: 'DELETE-FACT', data: { nFSid: x.nFSid, total: this.factlist.length } });
        // if(this.factlist.length == 1){
        //   this.viewFactDetail(this.factlist[0]);
        // }
        if (!this.factlist.length) {
          this.back();
        }
      }
    } else {
      this.tost.error(this.translate.instant('FACTS.DATA.DELETE_FAILED', { error: res.error }));
    }
  }

  async getCardEvent(e: toolEvents, x, i: number) {
    if (e.event == 'VIEW') {
    } else if (e.event == 'DELETE') {

      const res = await this.factService.deleteFact(x.nFSid);
      if (res && res.msg == 1) {
        if (x.nFSid) {
          this.factlist.splice(i, 1);
          this.cdr.detectChanges();
          this.OnEvent.emit({ event: 'DELETE-FACT', data: { nFSid: x.nFSid, total: this.factlist.length } });
          // if(this.factlist.length == 1){
          //   this.viewFactDetail(this.factlist[0]);
          // }
          if (!this.factlist.length) {
            this.back();
          }
        }
      } else {
        this.tost.error(this.translate.instant('FACTS.DATA.DELETE_FAILED', { error: res.error }));
      }

    }

  }



  back() {
    this.OnEvent.emit({ event: 'CLOSE', data: {} });
  }


  edit(x) {
    this.OnEvent.emit({ event: 'EDIT-Q-FACT', data: x });
  }


  convertToFullFact(x) {
    this.OnEvent.emit({ event: 'CONVERT-TO-FACT', data: x });
  }

}
