import { CommonModule } from '@angular/common';
import { booleanAttribute, ChangeDetectorRef, Component, Input, OnInit } from '@angular/core';
import { IconComponent } from '../../../shared/components/icon/icon.component';
import { MatCheckboxModule } from '@angular/material/checkbox';
import { AvatarComponent } from '../../../shared/components/avatar/avatar.component';
import { MatTooltipModule } from '@angular/material/tooltip';
import { ButtonComponent } from '../../../shared/components/button/button.component';
import { SkeletonComponent } from '../../../shared/components/skeleton/skeleton.component';
import { IndividualService } from '../../services/individual/individual.service';
import { DocInfo } from '../../../pdf/interfaces/pdf.interface';
import { TostbarService } from '../../../core/services/tost/tostbar.service';
import { FormsModule } from '@angular/forms';
import { CommonfunctionService } from '../../../core/utility/commonfunction.service';

@Component({
  selector: 'location-share',
  standalone: true,
  imports: [CommonModule, IconComponent, MatCheckboxModule, AvatarComponent, MatTooltipModule, ButtonComponent, SkeletonComponent, FormsModule],
  templateUrl: './location-share.component.html',
  styleUrl: './location-share.component.scss'
})
export class LocationShareComponent implements OnInit {

  @Input({ transform: booleanAttribute }) head: boolean = false;
  @Input() docInfo: DocInfo = {} as DocInfo;
  @Input() userList: any = [];
  @Input() mode: string = 'dark';

  @Input() type: string = ''; // "F/W/D"
  @Input() nId: string = null;

  @Input() isLocationShared: boolean = false;
  @Input() nCaseid: string = null;
  cUrl: string = '';
  isChanged: boolean = false;
  isLoading: boolean = false;
  locationUrl: string = '';
  @Input() nUserid: string;

  constructor(private individualS: IndividualService, private tost: TostbarService, private cdr: ChangeDetectorRef, private cf: CommonfunctionService) { }

  async ngOnInit() {
    const nFSid = this.nId;

    if (this.isLocationShared || (this.type == 'F' && nFSid)) {
      const users = await this.individualS.sharedusers(this.docInfo.nBundledetailid) || [];
      this.userList.map(f => f.isSelected = (users.findIndex(m => m.nUserid == f.nUserid) > -1))


      if (this.docInfo) {
        this.cUrl = `${location.origin}/individual/doc/${encodeURIComponent(JSON.stringify([[[this.docInfo.nBundledetailid, 1, 0, nFSid || null]], this.nCaseid]))}`;
      }

      this.cdr.detectChanges();
    }
  }


  async send() {

    this.isLoading = true;
    // if (!this.userList.filter(f => f.isSelected).length) {
    //   return;
    // }
    if (this.isLocationShared) {
      const mdl = {
        nBundledetailid: this.docInfo.nBundledetailid,
        jUsers: JSON.stringify(this.userList.filter(f => f.isSelected).map(m => m.nUserid)),
      }
      const res = await this.individualS.shared_to_users(mdl);
      if (res) {
        this.tost.openSnackBar(`File Shared Successfully`, '');
        this.isChanged = false;
        this.isLoading = false;
      }
    } else {
      const mdl = {
        nId: this.nId,
        jUsers: JSON.stringify(this.userList.filter(f => f.isSelected).map(m => m.nUserid)),
        cType: this.type,
        nCaseid: this.nCaseid
      }

      const res = await this.individualS.update_sharelink(mdl);
      if (res) {
        this.tost.openSnackBar('Users updated', '');
        this.isChanged = false;
        this.isLoading = false;
      }
    }
  }


  updateShare() {

  }

  copyText() {
    this.cf.copyText(this.cUrl)
    this.tost.openSnackBar('Copied!', '');
  }

}
