import { ChangeDetectionStrategy, ChangeDetectorRef, Component, EventEmitter, Input, OnInit, Output, SimpleChanges, ViewChild } from '@angular/core';
import { TranslateModule } from '@ngx-translate/core';
import { CommonModule } from '@angular/common';
import { ChooseIssueComponent } from '../../../../shared/components/issues/choose-issue/choose-issue.component';
import { selectedContactList, selectedIssues } from '../../../../shared/interfaces/issue.interface';
import { ButtonComponent } from '../../../../shared/components/button/button.component';
import { MatDialog } from '@angular/material/dialog';
import { CreateissueComponent } from '../../../../realtime/components/issues/createissue/createissue.component';
import { IconComponent } from '../../../../shared/components/icon/icon.component';
import { MatCheckboxModule } from '@angular/material/checkbox';
import { AvatarComponent } from '../../../../shared/components/avatar/avatar.component';
import { MatTooltipModule } from '@angular/material/tooltip';
import { factAssigneeType, myTeamUsers } from '../../../interfaces/pdf.interface';
import { ChooseContactComponent } from '../../../../shared/components/contacts/choose-contact/choose-contact.component';
import { SelectedContactComponent } from '../../../../shared/components/contacts/selected-contact/selected-contact.component';
import { CommonService } from '../../../../shared/services/common/common.service';
import { SelectedTasksComponent } from '../../../../shared/components/tasks/selected-tasks/selected-tasks.component';
import { ChooseTaskComponent } from '../../../../shared/components/tasks/choose-task/choose-task.component';
import { SharedViewComponent } from '../../../../shared/components/shared-view/shared-view.component';
import { RolepermitService } from '../../../../core/services/permission/rolepermit.service';
@Component({
  selector: 'fact-assignee',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [ChooseIssueComponent, ButtonComponent, IconComponent, MatCheckboxModule, AvatarComponent, MatTooltipModule, ChooseContactComponent, SelectedContactComponent, SelectedTasksComponent, ChooseTaskComponent, SharedViewComponent, TranslateModule, CommonModule],
  templateUrl: './fact-assignee.component.html',
  styleUrl: './fact-assignee.component.scss'
})
export class FactAssigneeComponent implements OnInit {
  @Input() nCaseid: string;
  @Input() selectedIssues: selectedIssues[];
  @Input() selectedContacts: selectedContactList[];
  @Input() selectedTasks: any[];
  @Input() userList: myTeamUsers[];
  @Input() isSubmitted: boolean;
  @ViewChild('issueListC') issueListC: ChooseIssueComponent;

  isShowAll: boolean = false;
  expandIssue: boolean = true;
  assignMode: factAssigneeType = null;

  @Output() OnEvent = new EventEmitter();

  isTaskPermission: boolean = true;
  isContactPermission: boolean = true;


  constructor(private cdr: ChangeDetectorRef, private dialog: MatDialog, private comman: CommonService,
    private rolepermit: RolepermitService
  ) { }


  async ngOnInit() {
    this.verifyPermission();
  }

  issueevnt(ev: any) {
    if (ev.type == 'CREATE') {
      this.createIssue();
    }
  }


  getIssue(event) {
    if (event.issueList.length > 4) {
      this.isShowAll = true;
      this.expandIssue = false;
      this.cdr.detectChanges();
    }
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes["isSubmitted"]) {
      this.cdr.detectChanges();
    }

  }

  createIssue(x?) {
    const dialog = this.dialog.open(CreateissueComponent, {
      width: '440px',
      height: 'calc(100% - 50px)',
      hasBackdrop: false,
      panelClass: ['noshadow', 'norounded'],
      position: {
        top: `50px`,
        right: `0px`,
      },
      data: { type: x ? 'E' : null, value: x ? x : null, current_session: { nCaseid: this.nCaseid } },
    });
    dialog.afterClosed().subscribe((result) => {
      this.issueListC.ngAfterViewInit();
      this.cdr.detectChanges();
    })
  }

  back() {
    this.OnEvent.emit({ event: 'BACK' });
  }

  submitFact() {
    this.OnEvent.emit({ event: 'SUBMIT', issues: this.selectedIssues, contacts: this.selectedContacts, tasks: this.selectedTasks, users: this.userList.filter(a => a.isSelected) });
  }

  OnContactEvent(event) {

    if (event.event == 'DELETE') {
      // const index = this.selectedContacts.findIndex(a => a.nContactid == event.data.nContactid);
      // if(index > -1) {
      //   this.selectedContacts.splice(index, 1);
      // }
    }
    this.cdr.detectChanges();
  }



  verifyPermission() {
    this.isTaskPermission = this.rolepermit.verifyPermission('TS');
    this.isContactPermission = this.rolepermit.verifyPermission('CT');
  }
}