import { ChangeDetectionStrategy, ChangeDetectorRef, Component, EventEmitter, Input, Output, SimpleChanges } from '@angular/core';
import { IconComponent } from '../../../../../shared/components/icon/icon.component';
import { ButtonComponent } from '../../../../../shared/components/button/button.component';
import { SourceCardComponent } from '../../../../../shared/components/source-card/source-card.component';
import { FactcardComponent } from '../../../../../pdf/components/linkviews/facts/factcard/factcard.component';
import { NavigateService } from '../../../../services/navigate/navigate.service';
import { navigateDocLinks, navigateModeType, navigateSubList } from '../../../../interfaces/navigate.interface';
import { CommonModule } from '@angular/common';
import { toolEvents } from '../../../../../pdf/interfaces/pdf.interface';
import { Subject } from 'rxjs';
import { finalFilterList } from '../../../../../shared/interfaces/filter.interface';
import { SharedViewComponent } from '../../../../../shared/components/shared-view/shared-view.component';
import { DoclinkcardComponent } from '../../doccard/doccard.component';

@Component({
  selector: 'app-doc-link',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [DoclinkcardComponent],
  templateUrl: './doc-link.component.html',
  styleUrl: './doc-link.component.scss'
})
export class DocLinkComponent {
  @Input() docInfo: any = {};
  @Input() nBundledetailid: string = null;
  @Output() noOfRecord: EventEmitter<number> = new EventEmitter();
  doclist: navigateDocLinks[] = [];
  @Output() OnEvent: EventEmitter<any> = new EventEmitter();
  @Input() onNavigateEvent: Subject<toolEvents>;
  jFilter: finalFilterList[] = [];
  @Input() selectedMode: navigateModeType;
  @Input() userList: any = [];
  @Input() nCaseid: string;
  @Input() sortBy: string = 'desc';


  constructor(private navigateService: NavigateService, private cdr: ChangeDetectorRef) { }

  async ngOnInit() {
    if (this.onNavigateEvent) {
      this.onNavigateEvent.subscribe((e: toolEvents) => {
        if (e.event == 'FILTER' && this.selectedMode == 'DL') {
          this.jFilter = e.data;
          this.initData()
        }
      });
    }
    this.initData()
  }

  async initData() {
    debugger;
    this.doclist = [];
    const res = await this.navigateService.getDocLinkLists(this.nBundledetailid, 'H', this.sortBy, 1, this.jFilter);
    this.noOfRecord.emit(res.length);
    if (res && res.length) {
      res.forEach((e) => {
        const subObj: navigateSubList = { nDocid: e.nDocid, nDMLids: e.nDMLids, nBundledetailid: e.nBundledetailid, jLinktype: e.jLinktype, jOTexts: e.jOTexts, cFilename: e.cFilename, cTab: e.cTab, cExhibitno: e.cExhibitno, cBundletag: e.cBundletag };

        const ind = this.doclist.findIndex((x) => x.nGId == e.nGId);
        if (ind == -1 || !e.nGId) { //
          this.doclist.push({ isIncomming: !e.nGId, nGId: Number(e.nGId), jDIds: e.jDIds, grouplink: e.grouplink, dCreateDt: e.dCreateDt, subList: [subObj], jIncomming: e.jIncomming, cCreateby: e.cCreateby });
        } else if (ind > -1) {
          this.doclist[ind].subList.push(subObj);
        }
      })
      this.cdr.detectChanges();
    }
  }

  OnViewEvent(x) {

    if (x?.event == "OPEN-IN-QUICK-VIEW") {
      this.OnEvent.emit(x);
    } else {
      if (x.jDIds?.length) {
        const id = x.jDIds[0]
        debugger
        this.OnEvent.next({
          event: 'VIEW-DETAIL-LINKS',
          data: {
            id: id, 
            jLinktype: x.grouplink,
            type: 'D'
          }
        });
      }
    }
  }

  async showShared(x) {

    const users = await this.navigateService.getSharedUsers(x.nDocid, 'D');
    this.userList.map(f => f.isSelected = (users.findIndex(m => m.nUserid == f.nUserid) > -1))
    this.doclist.forEach(doc => {
      doc.subList.forEach(element => {
        if (element.nDMLids != x.nDMLids) {
          element['showShared'] = false;
        }
      });
    });
    x['showShared'] = !x['showShared']
    this.cdr.detectChanges();
  }


  ngOnChanges(changes: SimpleChanges): void {
    if (changes && changes['sortBy'] && !changes['sortBy'].firstChange) {
      this.initData();
    }
  }

}
