import { ChangeDetectionStrategy, ChangeDetectorRef, Component, EventEmitter, Input, OnInit, OnChanges, Output, SimpleChanges } from '@angular/core';
import { DocInfo, myTeamUsers, toolEvents } from '../../../../interfaces/pdf.interface';
import { FactService } from '../../../../../shared/services/fact/fact.service';
import { factdata, factdetailmode, factIssues, factlinkfiles } from '../../../../../shared/interfaces/fact.interface';
import { FactcardComponent } from '../factcard/factcard.component';
import { IconComponent } from '../../../../../shared/components/icon/icon.component';
import { FactdetailComponent } from '../factdetail/factdetail.component';
import { CommonService } from '../../../../../shared/services/common/common.service';
import { SelectedContactComponent } from '../../../../../shared/components/contacts/selected-contact/selected-contact.component';
import { selectedContactList, selectedTaskList } from '../../../../../shared/interfaces/issue.interface';
import { SharedViewComponent } from '../../../../../shared/components/shared-view/shared-view.component';
import { SelectedTasksComponent } from '../../../../../shared/components/tasks/selected-tasks/selected-tasks.component';
import { TostbarService } from '../../../../../core/services/tost/tostbar.service';
import { SourceCardComponent } from '../../../../../shared/components/source-card/source-card.component';
import { EmptyComponent } from '../../../../../shared/components/empty/empty.component';
import { LocationShareComponent } from '../../../../../userpanel/components/location-share/location-share.component';
import { CommonModule } from '@angular/common';
import { AvatarComponent } from '../../../../../shared/components/avatar/avatar.component';
import { ContactdetailComponent } from '../../../../../shared/components/contacts/contactdetail/contactdetail.component';

import { TranslateModule, TranslateService } from '@ngx-translate/core';
import { ErrorHandlerUtil } from '../../../../../userpanel/utility/error-handler.util';

@Component({
  selector: 'factdata',
  standalone: true,
  imports: [FactcardComponent, IconComponent, CommonModule, FactdetailComponent, SelectedContactComponent, SelectedTasksComponent, SharedViewComponent, SourceCardComponent, EmptyComponent, LocationShareComponent, AvatarComponent, ContactdetailComponent, TranslateModule],
  changeDetection: ChangeDetectionStrategy.OnPush,
  templateUrl: './factdata.component.html',
  styleUrl: './factdata.component.scss'
})
export class FactdataComponent implements OnInit, OnChanges {
  @Input() docInfo: DocInfo = {} as DocInfo;
  @Input() nCaseid: string;
  @Input() fullMode: boolean = false;
  @Output() OnEvent = new EventEmitter<toolEvents>();
  @Input() linkIds: string[] = [];
  @Input() nUserid: string;
  @Input() userList: myTeamUsers[] = [];
  isListview: boolean = true;
  isLoading: boolean = true;

  factlist: factdata[] = [];


  currentFactDetail: factdata = {} as factdata;

  isError: boolean = false;
  // userList: myTeamUsers[] = [];

  factMode: factdetailmode = null;
  selectedContacts: selectedContactList[] = [];
  selectedTasks: selectedTaskList[] = [];
  selectedUsers: myTeamUsers[] = [];

  isFullViewLoading: boolean = false;
  nFSid: string;
  type: string = '';
  constructor(private readonly factService: FactService, private readonly common: CommonService, private readonly cdr: ChangeDetectorRef, private readonly tost: TostbarService, private readonly translate: TranslateService) {
  }

  ngOnInit(): void {
    void this.loadData();
  }

  private async loadData(): Promise<void> {
    if (this.linkIds.length === 1) {
      this.isListview = false;
    }
    this.factlist = await this.factService.getFactDetails(this.linkIds);

    if (!this.factlist.length) {
      this.isError = true;
      this.isLoading = false;
      this.cdr.detectChanges();
      return;
    }

    if (!this.isListview) {
      this.viewFactDetail(this.factlist[0]);
    }

    this.isLoading = false;
    this.cdr.detectChanges();

    if (this.factlist.length > 0) {
      const resUnknown = await this.factService.getFactIssuesAndLinks(this.linkIds) as unknown;
      if (Array.isArray(resUnknown) && resUnknown.length) {
        const issues = (resUnknown[0] as factIssues[]) || [];
        const linkfiles = (resUnknown[1] as factlinkfiles[]) || [];
        this.factlist.forEach(a => { a.issueList = issues.filter(b => b.nFSid === a.nFSid); });
        this.factlist.forEach(a => { a.filelinks = linkfiles.filter(b => b.nFSid === a.nFSid); });
      }
    }
    this.userList = await this.common.getMyTeamUsers(this.nCaseid);
    this.cdr.detectChanges();
  }

  async viewFactDetail(x: factdata): Promise<void> {
    this.currentFactDetail = x;
    this.isListview = false;
    this.cdr.detectChanges();
  }

  back() {
    this.OnEvent.emit({ event: 'CLOSE', data: {} });
  }


  backToFactDetail() {
    if (this.linkIds.length > 1) {
      this.currentFactDetail = null;
      this.isListview = true;
      this.cdr.detectChanges();
    } else {
      this.back();
    }
  }



  async OpenFullView(x: factdata, mode: factdetailmode): Promise<void> {
    this.nFSid = x.nFSid;

    if (this.factMode && this.factMode === mode) {
      this.factMode = null;
      this.selectedContacts = [];
      this.selectedTasks = [];
      this.selectedUsers = [];
      this.isFullViewLoading = false;
      this.cdr.detectChanges();
      return;
    }

    this.factMode = mode;

    if (this.isFullViewLoading) {
      return;
    }

    this.isFullViewLoading = true;
    this.cdr.detectChanges();

    try {
      switch (mode) {
        case 'C':
          await this.loadFullViewContacts(x.nFSid);
          break;
        case 'T':
          await this.loadFullViewTasks(x.nFSid);
          break;
        case 'S':
          await this.loadFullViewShares(x.nFSid);
          break;
        default:
          break;
      }
    } finally {
      this.isFullViewLoading = false;
      this.cdr.detectChanges();
    }
  }

  private async loadFullViewContacts(nFSid: string): Promise<void> {
    this.selectedContacts = await this.factService.getFactContact(nFSid);
  }

  private async loadFullViewTasks(nFSid: string): Promise<void> {
    const resUnknown = await this.factService.getFactTask(nFSid) as unknown;
    const tasks = Array.isArray(resUnknown) ? (resUnknown[0] as selectedTaskList[]) || [] : [];
    const usersArr = Array.isArray(resUnknown) ? (resUnknown[1] as myTeamUsers[]) || [] : [];
    const remindersArr = Array.isArray(resUnknown) ? (resUnknown[2] as any[]) || [] : [];

    this.selectedTasks = tasks;
    this.selectedTasks.forEach(task => {
      const teamlist = usersArr.filter(u => Array.isArray((u as any).jTaskid) ? (u as any).jTaskid.includes(task.nTaskid) : false);
      (task as any)['teamlist'] = teamlist;
      const row = remindersArr.filter(r => r.nTaskid === task.nTaskid);
      (task as any)['jReminders'] = row.length ? row[0].jReminders : [];
    });
  }

  private async loadFullViewShares(nFSid: string): Promise<void> {
    this.selectedUsers = await this.factService.getFactShare(nFSid);
    this.userList.forEach(f => { f.isSelected = (this.selectedUsers.findIndex(m => m.nUserid === f.nUserid) > -1); });
  }

  async getCardEvent(e: toolEvents, x: factdata, i: number): Promise<void> {
    if (e.event === 'VIEW') {
      await this.handleViewEvent(e, x);
    } else if (e.event === 'DELETE') {
      await this.handleDeleteEvent(x, i);
    }
  }

  private async handleViewEvent(e: toolEvents, x: factdata): Promise<void> {
    if (this.type === e.data && this.nFSid === x.nFSid) {
      this.nFSid = null;
      this.type = '';
    } else {
      this.nFSid = x.nFSid;
      this.type = e.data as string;
    }
    await this.OpenFullView(x, e.data as factdetailmode);
  }

  private async handleDeleteEvent(x: factdata, index: number): Promise<void> {
    const res = await this.factService.deleteFact(x.nFSid) as { msg?: number; error?: string } | null;
    if (res?.msg === 1) {
      if (x.nFSid) {
        this.factlist.splice(index, 1);
        this.cdr.detectChanges();
        this.OnEvent.emit({ event: 'DELETE-FACT', data: { nFSid: x.nFSid, total: this.factlist.length } });
        if (!this.factlist.length) {
          this.back();
        }
      }
      return;
    }
    const errMsg = ErrorHandlerUtil.getErrorMessage(res);
    throw new Error(this.translate.instant('FACTS.DATA.DELETE_FAILED', { error: errMsg }));
  }

  openBigFactSheet(): void {
    if (!this.currentFactDetail?.nFSid) {
      return;
    }
    this.OnEvent.emit({ event: 'BIG-FACT', data: { nFSid: this.currentFactDetail.nFSid } });
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['linkIds'] && !changes['linkIds'].firstChange) {
      try {
        if (!changes['linkIds'].previousValue.every((value: any, index: number) => value === changes['linkIds'].currentValue[index])) {
          this.ngOnInit();
        }
      } catch (error) {
        throw new Error(ErrorHandlerUtil.getErrorMessage(error));
      }
    }
  }

  openFactLink(e: { event: string; data: unknown }): void {
    this.OnEvent.emit(e as toolEvents);
  }

}
