import { ChangeDetectorRef, Component, EventEmitter, Input, Output, SimpleChanges } from '@angular/core';
import { NavigateService } from '../../../services/navigate/navigate.service';
import { IssueDetail, LinkDetail, navigateModeType, navigateSubList } from '../../../interfaces/navigate.interface';
import { FactcardComponent } from '../../../../pdf/components/linkviews/facts/factcard/factcard.component';
import { WebcardComponent } from '../webcard/webcard.component';
import { DoclinkcardComponent } from '../doccard/doccard.component';
import { NgClass, NgIf } from '@angular/common';
import { Subject } from 'rxjs';
import { toolEvents } from '../../../../pdf/interfaces/pdf.interface';



@Component({
  selector: 'app-allnavigate',
  standalone: true,
  imports: [FactcardComponent, WebcardComponent, DoclinkcardComponent, NgIf, NgClass],
  templateUrl: './allnavigate.component.html',
  styleUrl: './allnavigate.component.scss'
})
export class AllnavigateComponent {
  @Input() viewmode: string;
  @Input() selectedMode: navigateModeType;
  @Input() nBundledetailid: string;
  @Input() jFilter: any[];
  @Output() noOfRecord: EventEmitter<number> = new EventEmitter();
  @Input() userList: any = [];
  @Input() nCaseid: string;
  @Output() OnEvent: EventEmitter<any> = new EventEmitter();
  @Input() onNavigateEvent: Subject<toolEvents>;

  @Input() sortBy: string = 'desc';
  constructor(private navigateService: NavigateService, private cdr: ChangeDetectorRef) { }
  list: any[] = [];
  nFSid: string;
  type: string;

  ngOnInit(): void {
    //Called after the constructor, initializing input properties, and the first call to ngOnChanges.
    //Add 'implements OnInit' to the class.
    this.initList();
    if (this.onNavigateEvent) {
      this.onNavigateEvent.subscribe((e: toolEvents) => {

        if (e.event == 'FILTER' && this.selectedMode == 'A') {

          this.jFilter = e.data;
          this.initList();
        }
      });
    }

  }

  async initList() {
    try {
      const res: any = await this.navigateService.getAll(this.nBundledetailid, 'H', this.sortBy, 1, this.jFilter);
      const templist = res?.[0] || [];
      this.list = []//[...templist];


      if (templist.length) {
        const issueDetails: IssueDetail[] = res[1] || [];
        const linkDetails: LinkDetail[] = res[2] || [];
        let usedLinkDetailIndexes: Set<number> = new Set();
        // linkDetails.sort((a, b) => a.cName?.localeCompare(b.cName, undefined, { sensitivity: 'base' }));


        templist.forEach((e) => {
          if (e.cSource === 'D') {
            const subObj: navigateSubList = {
              nDocid: e.nDocid,
              nDMLids: e.nDMLids,
              nBundledetailid: e.nBundledetailid,
              jLinktype: e.jLinktype,
              jOTexts: e.jOTexts,
              cFilename: e.cFilename,
              cTab: e.cTab,
              cExhibitno: e.cExhibitno,
              cBundletag: e.cBundletag,
            };
            const ind = this.list.findIndex((x) => x.nGId === Number(e.nGId));
            if (ind === -1 || !e.nGId) {
              let tempobj = {
                isIncomming: !e.nGId,
                nGId: Number(e.nGId),
                jDIds: e.jDIds,
                grouplink: e.grouplink,
                dCreateDt: e.dCreateDt,
                subList: [subObj],
                jIncomming: e.jIncomming,
                cCreateby: e.cCreateby
              };
              e.nGId = Number(e.nGId);
              const temp = Object.assign(e, tempobj);
              this.list.push(temp);
            } else {
              if (!this.list[ind]['subList']) {
                this.list[ind]['subList'] = [];
              }
              this.list[ind]['subList'].push(subObj);
            }
          } else if (e.cSource === 'F' || e.cSource === 'FL') {
            e.issueList = issueDetails.filter(x => x.jFSids.includes(e.nFSid));
            e.linkfile = linkDetails.filter(x => x.nFSid === e.nFSid);
            this.list.push(e);
          }
          else {
            this.list.push(e);
          }
        });
      }
      this.noOfRecord.emit(templist.length);
    } catch (error) {
      console.error('Error initializing list:', error);
    } finally {
      this.cdr.detectChanges();
    }
  }

  OnViewEvent(x, type) {
    debugger;

    if (x?.event == "OPEN-IN-QUICK-VIEW") {
      this.OnEvent.emit(x);
    } else {
      this.OnEvent.next({
        event: 'VIEW-DETAIL-LINKS',
        data: {
          id: type == 'F' ? x.nFSid : type == 'W' ? x.nWebid : x.jDIds[0],
          jLinktype: type == 'D' ?  x.grouplink : x.jLinktype,
          type: type
        }
      });
    }
  }


  async getCardEvent(e: any, x, i: number) {
    debugger;
    if (this.type == e.data && this.nFSid == x.nFSid) {
      this.nFSid = null;
      this.type = '';
    } else {
      this.nFSid = x.nFSid;
      this.type = e.data;
    }
    if (e.event == 'VIEW') {
      e.x = x;
      this.OnEvent.next(e);
    }
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes && changes['sortBy'] && !changes['sortBy'].firstChange) {
      this.initList();
    }
  }
}
