@Component({
  selector: 'app-navigate',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [IconComponent, CommonModule, ButtonComponent,
    FactChronologyComponent, FactContactComponent, FactLinkComponent, FiltersComponent, DocLinkComponent,
    WebLinkComponent, TasklinkComponent, SelectedContactComponent, SelectedTasksComponent, SharedViewComponent,
    LocationShareComponent, AvatarComponent, ContactdetailComponent, NgScrollbarModule, MatTooltipModule, QfactComponent, AllnavigateComponent,
    EmptyComponent, AllLinksComponent, QuickPreviewComponent],
  templateUrl: './navigate.component.html',
  styleUrl: './navigate.component.scss'
})
export class NavigateComponent {
  @Input() docInfo: DocInfo = {} as DocInfo;
  @Input() nCaseid: string;
  @Output() OnEvent = new EventEmitter<toolEvents>();
  @ViewChild('textarea') textarea!: ElementRef;
  @ViewChild('downbtn') parent!: ElementRef;
  @Input() userList: any = [];
  @Input() nViewissueid: number = 0;

  // @ViewChild('downbtn', { static: true }) parent!: ElementRef;
  textareaHeight: any = window.innerHeight;

  private isResizing = false;
  private startY: number = 0;
  private totalMovement: number = 0;
  selectedTab: any = 'A';
  viewmode: any = 'M';
  selectedMode: any = 'A';
  nFSid: string = null;
  slectedisempty: any = false;
  showfilter: boolean = false;
  // factsby: string = 'H';
  // Linktype: string = 'F';
  // tasktype: string = 'F';
  tablist: any = [
    {
      name: 'All',
      type: 'A',
      isactive: false
    },
    {
      name: 'qFact',
      type: 'QF',
      isactive: false
    },
    {
      name: 'Fact',
      type: 'F',

      isactive: false
    },

    {
      name: 'Link',
      type: 'L',

      isactive: false
    },
    // {
    //   name: 'Tasks',
    //   type: 'T',
    //   isactive: false
    // },
  ];


  @Input() nBundledetailid: string = null;
  noOfRecord: number = 0;
  companylist: any = [];
  checkNavInfo: checkNavRes;
  pageNo: number = 1;
  // userList: myTeamUsers[] = [];



  factMode: factdetailmode = null;

  selectedContacts: selectedContactList[] = [];
  selectedTasks: selectedTaskList[] = [];
  selectedUsers: myTeamUsers[] = [];

  isFullViewLoading: boolean = false;
  valueUpdateFCH: Subject<toolEvents> = new Subject();
  valueUpdateFCO: Subject<toolEvents> = new Subject();
  valueUpdateFL: Subject<toolEvents> = new Subject();
  valueUpdateDL: Subject<toolEvents> = new Subject();
  valueUpdateWL: Subject<toolEvents> = new Subject();
  valueUpdateTFL: Subject<toolEvents> = new Subject();
  valueUpdateTFC: Subject<toolEvents> = new Subject();
  valueUpdateA: Subject<toolEvents> = new Subject();
  valueUpdateQF: Subject<toolEvents> = new Subject();
  valueUpdateAL: Subject<toolEvents> = new Subject();

  filterUpdate: Subject<toolEvents> = new Subject();

  sortBy: string = 'desc'

  currentfact: any;

  constructor(private navigateService: NavigateService, private cdr: ChangeDetectorRef, private common: CommonService, private factService: FactService, private renderer: Renderer2,
    private myfileS: MyfileService) { }

  async ngOnInit() {
    // this.userList = await this.common.getMyTeamUsers(this.nCaseid);
    // this.docInfo = { nBundledetailid: 555364, cFilename: 'A12 Claimant\'s Submission to challenge the PO1_repaired.pdf', cBundle: 'Bundle 1', cPage: '10 - 20', cRefpage: null, cFiletype: 'PDF', cTab: 'A1', cPath: '', cExhibitno: 'Exhibit 1', nBundleid: 12, nRotate: 0 };
    this.nBundledetailid = this.docInfo.nBundledetailid;
    //Called after the constructor, initializing input properties, and the first call to ngOnChanges.
    //Add 'implements OnInit' to the class.
    if (!this.nBundledetailid) { }
    this.navigateService.checkNavData(this.nBundledetailid).then(res => {
      this.checkNavInfo = res;
      this.cdr.markForCheck();
      console.log(this.checkNavInfo);

      this.selecttab(this.tablist[0]);
      // for (let element of this.tablist) {
      //   if (element.type == 'F' && (this.checkNavInfo.isfact == true || this.checkNavInfo.iscontact == true)) {
      //     element.isactive = true;
      //     this.selecttab(element);
      //     break;
      //   } else if (element.type == 'L' && (this.checkNavInfo.isdoclink == true || this.checkNavInfo.isfactlink == true || this.checkNavInfo.isweblink == true)) {
      //     element.isactive = true;
      //     this.selecttab(element);
      //     break;
      //   } else if (element.type == 'T' && (this.checkNavInfo.isfacttask == true && this.checkNavInfo.isfiletask == true)) {
      //     element.isactive = true;
      //     this.selecttab(element);
      //     break;
      //   }
      // }
    })


    if (this.nViewissueid) {
       this.showfilter = true;

      let ev: toolEvents = { "event": "FILTER", "data": [{ "name": "ISSUE", "type": "V", "value": [this.nViewissueid] }] }
      this.valueUpdateA.next(ev)
      setTimeout(() => {        
        this.upfilter();
      });
    }
    this.cdr.detectChanges();
  }
  ngAfterViewInit(): void {
  }


  onResize(dimensions: DOMRectReadOnly) {
    console.log('Textarea resized', dimensions);
    // Add your resize logic here
  }

  selectSubtab(type: navigateModeType) {
    this.selectedMode = type;
    this.factMode = null;
    this.filterUpdate.next({ event: 'CLEAR', data: null });
    this.cdr.detectChanges();
  }

  async selecttab(x: { type: string }) {
    if (this.selectedTab === x.type) return;

    this.selectedTab = x.type;

    if (x.type === 'L') {
      if (this.checkNavInfo.isalllinks) {
        this.selectedMode = 'AL';
      } else if (this.checkNavInfo.isfactlink) {
        this.selectedMode = 'FL';
      } else if (this.checkNavInfo.isdoclink) {
        this.selectedMode = 'DL';
      } else if (this.checkNavInfo.isweblink) {
        this.selectedMode = 'WL';
      } else {
        this.selectedMode = 'TFC';
      }
      this.viewmode = 'M';
    } else {
      const modeMap: { [key: string]: string } = {
        F: 'FCH',
        QF: 'QF',
        A: 'A'
      };
      this.selectedMode = modeMap[x.type] || 'TFC';
    }

    this.filterUpdate.next({ event: 'CLEAR', data: null });
    this.cdr.detectChanges();
  }




  async getCardEvent(e: any) {
    if (e.event == 'VIEW') {
      this.OpenFullView(e.x, e.data);
    }
    else if (e.event == 'OPEN-IN-QUICK-VIEW') {
      this.handleQuickView(e);
    }
    else {
      this.OnEvent.emit(e);
    }
  }
  async OpenFullView(x: factdata, mode: factdetailmode) {

    this.nFSid = x.nFSid;
    if (this.factMode && this.factMode == mode) {
      this.factMode = null;
      this.selectedContacts = [];
      this.selectedTasks = [];
      this.selectedUsers = [];
      this.isFullViewLoading = false;
      this.cdr.detectChanges();
      return;
    }

    this.factMode = mode;



    if (this.isFullViewLoading) {
      return
    }
    this.isFullViewLoading = true;
    this.cdr.detectChanges();



    if (mode == 'C') {
      this.selectedContacts = await this.factService.getFactContact(x.nFSid);
    } else if (mode == 'T') {
      const res: any = await this.factService.getFactTask(x.nFSid);

      this.selectedTasks = res[0] || [];
      this.selectedTasks.map(a => {
        var user = [];
        if (res[1]) {
          user = res[1].filter(b => b.jTaskid.includes(a.nTaskid));
        }
        a['teamlist'] = user ? user : [];
        this.selectedTasks.map(a => {
          var remiders = [];
          if (res[2]) {
            let row = res[2].filter(b => b.nTaskid == a.nTaskid);
            remiders = row.length ? row[0].jReminders : [];
          }
          a['jReminders'] = remiders ? remiders : [];
        });
      });
    } else if (mode == 'S') {
      this.selectedUsers = await this.factService.getFactShare(x.nFSid);
      this.userList.map(f => f.isSelected = (this.selectedUsers.findIndex(m => m.nUserid == f.nUserid) > -1))
    }



    this.isFullViewLoading = false;
    this.cdr.detectChanges();

  }




  adjustHeightDown(textarea: HTMLTextAreaElement) {
    textarea.style.zIndex = `99`;
  }


  adjustHeightUp(textarea: HTMLTextAreaElement) {

    const currentHeight = textarea.offsetHeight;
    if (currentHeight < 500) {

      requestAnimationFrame(() => {
        textarea.classList.add('transition-all');
        textarea.style.height = `0px`;
        this.textareaHeight = 0;
        setTimeout(() => {
          textarea.classList.remove('transition-all');
          this.showfilter = false;
        }, 300);
      });
    } else if (currentHeight >= 500) {
      this.textareaHeight = window.innerHeight;
    }
    this.cdr.detectChanges();
  }





  OnFilterEvents(e: toolEvents) {
    if (e.event == 'BACK') {
      this.showfilter = false;
    }
  }


  private startX: number = 0;
  private animationFrameId: number | null = null;

  @HostListener('mousedown', ['$event'])
  initResize(event: MouseEvent): void {
    if (this.parent) {
      if (event.target === this.parent.nativeElement) { // Check if the click is on the resizable area
        event.preventDefault();
        this.isResizing = true;
        this.startY = event.clientY;
        // this.startWidth = this.leftWidth;
        this.renderer.setStyle(document.body, 'cursor', 'ns-resize');
      }
    }
  }

  @HostListener('window:mousemove', ['$event'])
  onMouseMove(event: MouseEvent): void {
    if (!this.isResizing) return;
    if (this.animationFrameId) {
      cancelAnimationFrame(this.animationFrameId);
    }
    this.animationFrameId = requestAnimationFrame(() => this.doResize(event));
  }

  @HostListener('window:mouseup')
  stopResize(): void {
    if (!this.isResizing) return;
    this.adjustHeightUp(this.textarea.nativeElement);
    this.isResizing = false;
    if (this.animationFrameId) {
      cancelAnimationFrame(this.animationFrameId);
    }
    this.renderer.setStyle(document.body, 'cursor', 'auto');
  }

  private doResize(event: MouseEvent): void {
    this.textareaHeight = Math.max(0, event.clientY);
    this.cdr.detectChanges();
    console.log('Resizing to:', this.textareaHeight, event.clientY, this.startX,);
  };

  OnFilterResult(e: toolEvents) {

    if (e.event == 'FILTER') {

      this['valueUpdate' + this.selectedMode].next(e);
    } else if (e.event == 'BACK') {
      this.showfilter = false;
      this.cdr.detectChanges();
    }
  }


  openfilter() {
    this.showfilter = true;
    this.cdr.detectChanges();
    this.textarea.nativeElement.classList.add('transition-all');
    this.textareaHeight = window.innerHeight;
    setTimeout(() => {
      this.textarea.nativeElement.classList.remove('transition-all');
    }, 300);
  }


  upfilter() {
    this.textarea.nativeElement.classList.add('transition-all');
    this.textarea.nativeElement.classList.add('duration-700');
    requestAnimationFrame(() => {
      this.textarea.nativeElement.style.height = `0px`;
      this.textareaHeight = 0;
      setTimeout(() => {
        this.textarea.nativeElement.classList.remove('transition-all');
        this.textarea.nativeElement.classList.remove('duration-700');
        this.showfilter = false;
      }, 300);
    });
  }

  handleSort() {
    this.sortBy = this.sortBy == 'asc' ? 'desc' : 'asc';
  }


  OnQuickPreviewEvent(e: any) {
    if (e.event == 'OPEN-FILE') {
      this.OnEvent.emit({ event: 'OPEN-FACT-LINK', data: e.data });
    }
  }
  handleQuickView(e: any) {
    if (this.factMode && this.factMode == 'QV') {
      this.factMode = null;
      this.selectedContacts = [];
      this.selectedTasks = [];
      this.selectedUsers = [];
      this.currentfact = null;
      this.cdr.detectChanges();
      return;
    }

    this.factMode = 'QV';
    this.currentfact = e.data;
    this.insertRecent();

  }

  async getrecentfile() {

    const params = {
      nCaseid: this.nCaseid,
      nSectionid: null,
      cType: 'N',
    }
    const res = await this.myfileS.getrecentfile(params);
    console.log('res', res);
  }

  async clearRecentFile() {
    var mdl = { nCaseid: this.nCaseid, nSectionid: null, cType: 'N' }
    const res: boolean = await this.myfileS.clearRecent(mdl);
    if (res)
      console.log('res', res);
  }

  async insertRecent() {

    if (!this.currentfact?.nBundledetailid) return;
    var mdl = { nCaseid: this.nCaseid, nSectionid: null, cType: 'N', nBDid: this.currentfact.nBundledetailid }
    const res: boolean = await this.myfileS.insertRecent(mdl);
    if (res)
      console.log('res', res);
  }
}

